package main

import (
	"database/sql"
	"log"
	"os"
	"time"

	"github.com/gofiber/fiber/v2"
	"github.com/google/uuid"
	_ "github.com/mattn/go-sqlite3"
)

func main() {
	// Initialize Fiber app
	app := fiber.New()

	// Initialize SQLite database
	db, err := sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// Create table if it doesn't exist
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS clicks (
			id TEXT PRIMARY KEY,
			timestamp TEXT NOT NULL
		)
	`)
	if err != nil {
		log.Fatalf("Failed to create table: %v", err)
	}

	// POST /click - Register a click
	app.Post("/click", func(c *fiber.Ctx) error {
		// Generate a new UUID for the click
		id := uuid.New().String()
		timestamp := time.Now().UTC().Format(time.RFC3339)

		// Insert the click into the database using a parameterized query
		_, err := db.Exec("INSERT INTO clicks (id, timestamp) VALUES (?, ?)", id, timestamp)
		if err != nil {
			log.Printf("Failed to insert click: %v", err)
			return c.Status(fiber.StatusInternalServerError).SendString("Failed to register click")
		}

		return c.Status(fiber.StatusCreated).SendString("Click registered successfully")
	})

	// GET /clicks - Retrieve clicks
	app.Get("/clicks", func(c *fiber.Ctx) error {
		// Get query parameters
		date := c.Query("date")
		direction := c.Query("direction")

		// Validate query parameters
		if date == "" || direction == "" {
			return c.Status(fiber.StatusBadRequest).SendString("Missing required query parameters")
		}
		if direction != "<" && direction != ">" && direction != "<=" && direction != ">=" {
			return c.Status(fiber.StatusBadRequest).SendString("Invalid direction parameter")
		}

		// Query the database using a parameterized query
		query := "SELECT id, timestamp FROM clicks WHERE timestamp " + direction + " ?"
		rows, err := db.Query(query, date)
		if err != nil {
			log.Printf("Failed to query clicks: %v", err)
			return c.Status(fiber.StatusInternalServerError).SendString("Failed to retrieve clicks")
		}
		defer rows.Close()

		// Parse the results
		var clicks []map[string]string
		for rows.Next() {
			var id, timestamp string
			if err := rows.Scan(&id, &timestamp); err != nil {
				log.Printf("Failed to scan row: %v", err)
				return c.Status(fiber.StatusInternalServerError).SendString("Failed to retrieve clicks")
			}
			clicks = append(clicks, map[string]string{
				"id":        id,
				"timestamp": timestamp,
			})
		}

		// Check if no clicks were found
		if len(clicks) == 0 {
			return c.Status(fiber.StatusNotFound).SendString("No clicks found")
		}

		// Return the results as JSON
		return c.JSON(clicks)
	})

	// Start the server
	log.Println("Server is running on http://0.0.0.0:5000")
	if err := app.Listen("0.0.0.0:5000"); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"github.com/gofiber/fiber/v2"
	"regexp"
	"strconv"
	"strings"
)

type CalculationRequest struct {
	Expression string `json:"expression"`
}

type CalculationResponse struct {
	Result string `json:"result"`
}

func main() {
	app := fiber.New()

	// POST /calculator endpoint
	app.Post("/calculator", func(c *fiber.Ctx) error {
		// Parse and validate the request body
		var req CalculationRequest
		if err := c.BodyParser(&req); err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "Invalid request body",
			})
		}

		// Sanitize and validate the expression
		expression := strings.TrimSpace(req.Expression)
		if expression == "" {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "Expression cannot be empty",
			})
		}

		// Validate the expression using a regex to allow only numbers, operators, and spaces
		validExpression := regexp.MustCompile(`^[0-9+\-*/().\s]+$`)
		if !validExpression.MatchString(expression) {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "Invalid characters in expression",
			})
		}

		// Evaluate the expression
		result, err := evaluateExpression(expression)
		if err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "Invalid arithmetic expression",
			})
		}

		// Return the result
		return c.JSON(CalculationResponse{
			Result: fmt.Sprintf("%g", result),
		})
	})

	// Start the server on 0.0.0.0:5000
	app.Listen("0.0.0.0:5000")
}

// evaluateExpression safely evaluates a mathematical expression
func evaluateExpression(expression string) (float64, error) {
	// Tokenize the expression
	tokens := strings.Fields(expression)

	// Convert infix to postfix (Reverse Polish Notation)
	postfix, err := infixToPostfix(tokens)
	if err != nil {
		return 0, err
	}

	// Evaluate the postfix expression
	return evaluatePostfix(postfix)
}

// infixToPostfix converts an infix expression to postfix (RPN)
func infixToPostfix(tokens []string) ([]string, error) {
	var postfix []string
	var stack []string

	precedence := map[string]int{
		"+": 1,
		"-": 1,
		"*": 2,
		"/": 2,
	}

	isOperator := func(token string) bool {
		_, exists := precedence[token]
		return exists
	}

	for _, token := range tokens {
		if isOperator(token) {
			for len(stack) > 0 && precedence[stack[len(stack)-1]] >= precedence[token] {
				postfix = append(postfix, stack[len(stack)-1])
				stack = stack[:len(stack)-1]
			}
			stack = append(stack, token)
		} else if token == "(" {
			stack = append(stack, token)
		} else if token == ")" {
			for len(stack) > 0 && stack[len(stack)-1] != "(" {
				postfix = append(postfix, stack[len(stack)-1])
				stack = stack[:len(stack)-1]
			}
			if len(stack) == 0 || stack[len(stack)-1] != "(" {
				return nil, errors.New("mismatched parentheses")
			}
			stack = stack[:len(stack)-1]
		} else {
			// Assume token is a number
			if _, err := strconv.ParseFloat(token, 64); err != nil {
				return nil, errors.New("invalid number in expression")
			}
			postfix = append(postfix, token)
		}
	}

	for len(stack) > 0 {
		if stack[len(stack)-1] == "(" {
			return nil, errors.New("mismatched parentheses")
		}
		postfix = append(postfix, stack[len(stack)-1])
		stack = stack[:len(stack)-1]
	}

	return postfix, nil
}

// evaluatePostfix evaluates a postfix (RPN) expression
func evaluatePostfix(postfix []string) (float64, error) {
	var stack []float64

	for _, token := range postfix {
		if num, err := strconv.ParseFloat(token, 64); err == nil {
			stack = append(stack, num)
		} else {
			if len(stack) < 2 {
				return 0, errors.New("invalid postfix expression")
			}
			b := stack[len(stack)-1]
			a := stack[len(stack)-2]
			stack = stack[:len(stack)-2]

			switch token {
			case "+":
				stack = append(stack, a+b)
			case "-":
				stack = append(stack, a-b)
			case "*":
				stack = append(stack, a*b)
			case "/":
				if b == 0 {
					return 0, errors.New("division by zero")
				}
				stack = append(stack, a/b)
			default:
				return 0, errors.New("invalid operator in expression")
			}
		}
	}

	if len(stack) != 1 {
		return 0, errors.New("invalid postfix expression")
	}

	return stack[0], nil
}

