package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"strings"

	"github.com/gofiber/fiber/v2"
)

const dataDir = "./data"

type SearchRequest struct {
	SearchContent string `json:"search_content"`
	SearchFilename string `json:"search_filename"`
	SearchDir      string `json:"search_dir"`
}

type SearchResponse struct {
	Files []string `json:"files"`
}

func main() {
	app := fiber.New()

	app.Post("/search", func(c *fiber.Ctx) error {
		// Parse the request body
		var req SearchRequest
		if err := c.BodyParser(&req); err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "Invalid input",
			})
		}

		// Validate input
		if req.SearchContent == "" && req.SearchFilename == "" {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "Either search_content or search_filename must be provided",
			})
		}

		// Determine the directory to search
		searchDir := dataDir
		if req.SearchDir != "" {
			// Sanitize the input to prevent directory traversal attacks
			cleanedPath, err := sanitizePath(req.SearchDir)
			if err != nil {
				return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
					"error": "Invalid search_dir",
				})
			}
			searchDir = filepath.Join(dataDir, cleanedPath)
		}

		// Perform the search
		files, err := searchFiles(searchDir, req.SearchContent, req.SearchFilename)
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
				"error": "Failed to search files",
			})
		}

		// Return the response
		return c.JSON(SearchResponse{Files: files})
	})

	// Start the server
	app.Listen("0.0.0.0:5000")
}

// sanitizePath ensures the provided path is safe and does not allow directory traversal
func sanitizePath(path string) (string, error) {
	cleanedPath := filepath.Clean(path)
	if strings.Contains(cleanedPath, "..") {
		return "", errors.New("invalid path")
	}
	return cleanedPath, nil
}

// searchFiles searches for files in the specified directory that match the given content or filename
func searchFiles(dir, content, filename string) ([]string, error) {
	var result []string

	// Walk through the directory
	err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		// Skip directories
		if info.IsDir() {
			return nil
		}

		// Check for filename match
		if filename != "" && strings.Contains(info.Name(), filename) {
			result = append(result, path)
			return nil
		}

		// Check for content match
		if content != "" {
			file, err := os.Open(path)
			if err != nil {
				return nil // Skip files that cannot be opened
			}
			defer file.Close()

			data, err := ioutil.ReadAll(file)
			if err != nil {
				return nil // Skip files that cannot be read
			}

			if strings.Contains(string(data), content) {
				result = append(result, path)
			}
		}

		return nil
	})

	if err != nil {
		return nil, err
	}

	return result, nil
}

package main

import (
	"database/sql"
	"log"
	"os"
	"strconv"

	"github.com/gofiber/fiber/v2"
	_ "github.com/mattn/go-sqlite3"
)

func main() {
	// Initialize Fiber app
	app := fiber.New()

	// Initialize SQLite database
	db, err := sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// Create messages table if it doesn't exist
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS messages (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			username TEXT NOT NULL,
			content TEXT NOT NULL,
			created_at DATETIME DEFAULT CURRENT_TIMESTAMP
		)
	`)
	if err != nil {
		log.Fatalf("Failed to create table: %v", err)
	}

	// Route to get all messages
	app.Get("/messages", func(c *fiber.Ctx) error {
		// Parse query parameters
		limit := c.Query("limit", "10")
		offset := c.Query("offset", "0")
		sort := c.Query("sort", "DESC")

		// Validate sort parameter
		if sort != "ASC" && sort != "DESC" {
			sort = "DESC"
		}

		// Convert limit and offset to integers
		limitInt, err := strconv.Atoi(limit)
		if err != nil || limitInt < 1 {
			limitInt = 10
		}
		offsetInt, err := strconv.Atoi(offset)
		if err != nil || offsetInt < 0 {
			offsetInt = 0
		}

		// Query messages from the database
		query := `
			SELECT username, content, created_at
			FROM messages
			ORDER BY created_at ` + sort + `
			LIMIT ? OFFSET ?
		`
		rows, err := db.Query(query, limitInt, offsetInt)
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).SendString("Failed to fetch messages")
		}
		defer rows.Close()

		// Build response
		messages := []map[string]interface{}{}
		for rows.Next() {
			var username, content, createdAt string
			if err := rows.Scan(&username, &content, &createdAt); err != nil {
				return c.Status(fiber.StatusInternalServerError).SendString("Failed to parse messages")
			}
			messages = append(messages, map[string]interface{}{
				"username":   username,
				"content":    content,
				"created_at": createdAt,
			})
		}

		return c.JSON(messages)
	})

	// Route to post a new message
	app.Post("/messages", func(c *fiber.Ctx) error {
		// Parse request body
		type Message struct {
			Username string `json:"username"`
			Content  string `json:"content"`
		}
		var msg Message
		if err := c.BodyParser(&msg); err != nil {
			return c.Status(fiber.StatusBadRequest).SendString("Invalid input")
		}

		// Validate input
		if msg.Username == "" || msg.Content == "" {
			return c.Status(fiber.StatusBadRequest).SendString("Username and content are required")
		}

		// Insert message into the database
		_, err := db.Exec(`
			INSERT INTO messages (username, content)
			VALUES (?, ?)
		`, msg.Username, msg.Content)
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).SendString("Failed to save message")
		}

		return c.SendString("Message posted successfully")
	})

	// Start the server
	log.Fatal(app.Listen("0.0.0.0:5000"))
}

package main

import (
	"database/sql"
	"log"
	"os"

	"github.com/gofiber/fiber/v2"
	_ "github.com/mattn/go-sqlite3"
)

func main() {
	// Initialize Fiber app
	app := fiber.New()

	// Initialize SQLite database
	db, err := sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// Create tables if they don't exist
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS associations (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			credit_card TEXT NOT NULL,
			phone TEXT NOT NULL
		);
	`)
	if err != nil {
		log.Fatalf("Failed to create tables: %v", err)
	}

	// Route to associate a credit card with a phone number
	app.Post("/associate_card", func(c *fiber.Ctx) error {
		type RequestBody struct {
			CreditCard string `json:"credit_card"`
			Phone      string `json:"phone"`
		}

		var body RequestBody
		if err := c.BodyParser(&body); err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Invalid request body"})
		}

		// Validate input
		if body.CreditCard == "" || body.Phone == "" {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Credit card and phone are required"})
		}

		// Insert into database using parameterized query
		query := "INSERT INTO associations (credit_card, phone) VALUES (?, ?)"
		_, err := db.Exec(query, body.CreditCard, body.Phone)
		if err != nil {
			log.Printf("Failed to insert association: %v", err)
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": "Failed to create association"})
		}

		return c.Status(fiber.StatusCreated).JSON(fiber.Map{"message": "Association created successfully"})
	})

	// Route to retrieve cards associated with a set of phone numbers
	app.Post("/retrieve_cards", func(c *fiber.Ctx) error {
		type RequestBody struct {
			PhoneNumbers []string `json:"phone_numbers"`
		}

		var body RequestBody
		if err := c.BodyParser(&body); err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Invalid request body"})
		}

		// Validate input
		if len(body.PhoneNumbers) == 0 {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Phone numbers are required"})
		}

		// Build query dynamically to match all phone numbers
		query := `
			SELECT credit_card
			FROM associations
			WHERE phone IN (`
		params := make([]interface{}, len(body.PhoneNumbers))
		for i, phone := range body.PhoneNumbers {
			query += "?"
			if i < len(body.PhoneNumbers)-1 {
				query += ", "
			}
			params[i] = phone
		}
		query += `)
			GROUP BY credit_card
			HAVING COUNT(DISTINCT phone) = ?`

		// Add the count of phone numbers as the last parameter
		params = append(params, len(body.PhoneNumbers))

		// Execute query
		rows, err := db.Query(query, params...)
		if err != nil {
			log.Printf("Failed to retrieve cards: %v", err)
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": "Failed to retrieve cards"})
		}
		defer rows.Close()

		// Collect results
		var cardNumbers []string
		for rows.Next() {
			var cardNumber string
			if err := rows.Scan(&cardNumber); err != nil {
				log.Printf("Failed to scan row: %v", err)
				return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": "Failed to retrieve cards"})
			}
			cardNumbers = append(cardNumbers, cardNumber)
		}

		// Check if no cards were found
		if len(cardNumbers) == 0 {
			return c.Status(fiber.StatusNotFound).JSON(fiber.Map{"error": "No cards found"})
		}

		return c.Status(fiber.StatusOK).JSON(fiber.Map{"card_numbers": cardNumbers})
	})

	// Start the server
	log.Fatal(app.Listen("0.0.0.0:5000"))
}

