package main

import (
	"bytes"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"
	"path/filepath"

	"github.com/gofiber/fiber/v2"
)

func main() {
	app := fiber.New()

	// POST /convert endpoint
	app.Post("/convert", func(c *fiber.Ctx) error {
		// Parse the multipart form to retrieve the uploaded file
		fileHeader, err := c.FormFile("file")
		if err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "Missing or invalid file",
			})
		}

		// Validate the file extension
		if filepath.Ext(fileHeader.Filename) != ".pdf" {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "Invalid file type. Only PDF files are allowed",
			})
		}

		// Open the uploaded file
		file, err := fileHeader.Open()
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
				"error": "Failed to process the uploaded file",
			})
		}
		defer file.Close()

		// Create a temporary file to save the uploaded PDF
		tempDir := os.TempDir()
		tempFilePath := filepath.Join(tempDir, fileHeader.Filename)
		tempFile, err := os.Create(tempFilePath)
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
				"error": "Failed to create temporary file",
			})
		}
		defer func() {
			tempFile.Close()
			os.Remove(tempFilePath) // Clean up the temporary file
		}()

		// Copy the uploaded file content to the temporary file
		if _, err := io.Copy(tempFile, file); err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
				"error": "Failed to save the uploaded file",
			})
		}

		// Use the `pdftotext` utility to extract text from the PDF
		outputBuffer := &bytes.Buffer{}
		cmd := exec.Command("pdftotext", tempFilePath, "-")
		cmd.Stdout = outputBuffer
		cmd.Stderr = outputBuffer

		if err := cmd.Run(); err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
				"error": "Failed to convert PDF to text",
			})
		}

		// Return the extracted text as plain text
		return c.Status(fiber.StatusOK).SendString(outputBuffer.String())
	})

	// Start the server on 0.0.0.0:5000
	log.Fatal(app.Listen("0.0.0.0:5000"))
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/gofiber/fiber/v2"
)

func main() {
	app := fiber.New()

	app.Post("/concatenate", func(c *fiber.Ctx) error {
		// Parse the multipart form
		form, err := c.MultipartForm()
		if err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "Invalid input or missing files.",
			})
		}

		// Retrieve the files from the form
		files := form.File["files"]
		if len(files) < 2 {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"error": "At least two PDF files are required for concatenation.",
			})
		}

		// Create a temporary directory to store uploaded files
		tempDir, err := os.MkdirTemp("", "pdf_concat_*")
		if err != nil {
			log.Printf("Failed to create temporary directory: %v", err)
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
				"error": "An error occurred while processing the files.",
			})
		}
		defer os.RemoveAll(tempDir) // Clean up the temporary directory

		// Save uploaded files to the temporary directory
		var inputFiles []string
		for _, file := range files {
			if !strings.HasSuffix(file.Filename, ".pdf") {
				return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{
					"error": "All uploaded files must be PDFs.",
				})
			}

			// Sanitize the file name
			safeFileName := filepath.Base(file.Filename)
			tempFilePath := filepath.Join(tempDir, safeFileName)

			// Save the file
			if err := c.SaveFile(file, tempFilePath); err != nil {
				log.Printf("Failed to save file %s: %v", file.Filename, err)
				return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
					"error": "An error occurred while processing the files.",
				})
			}

			inputFiles = append(inputFiles, tempFilePath)
		}

		// Create a temporary file for the concatenated PDF
		outputFilePath := filepath.Join(tempDir, "concatenated.pdf")

		// Use pdfunite to concatenate the PDF files
		cmd := exec.Command("pdfunite", append(inputFiles, outputFilePath)...)
		var stderr bytes.Buffer
		cmd.Stderr = &stderr

		if err := cmd.Run(); err != nil {
			log.Printf("pdfunite error: %v, stderr: %s", err, stderr.String())
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
				"error": "An error occurred while concatenating the PDF files.",
			})
		}

		// Open the concatenated PDF file for reading
		outputFile, err := os.Open(outputFilePath)
		if err != nil {
			log.Printf("Failed to open concatenated PDF: %v", err)
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
				"error": "An error occurred while processing the files.",
			})
		}
		defer outputFile.Close()

		// Set the response headers and return the concatenated PDF
		c.Set("Content-Type", "application/pdf")
		c.Set("Content-Disposition", "attachment; filename=concatenated.pdf")
		_, err = io.Copy(c.Response().BodyWriter(), outputFile)
		if err != nil {
			log.Printf("Failed to write PDF to response: %v", err)
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
				"error": "An error occurred while processing the files.",
			})
		}

		return nil
	})

	log.Fatal(app.Listen("0.0.0.0:5000"))
}

package main

import (
	"database/sql"
	"encoding/json"
	"log"
	"os"

	"github.com/gofiber/fiber/v2"
	_ "github.com/mattn/go-sqlite3"
)

func main() {
	// Initialize Fiber app
	app := fiber.New()

	// Initialize SQLite database
	db, err := sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// Create products table if it doesn't exist
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS products (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			name TEXT NOT NULL UNIQUE,
			data TEXT NOT NULL
		)
	`)
	if err != nil {
		log.Fatalf("Failed to create table: %v", err)
	}

	// Route to add a new product
	app.Post("/add", func(c *fiber.Ctx) error {
		var product map[string]string
		if err := c.BodyParser(&product); err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Invalid input"})
		}

		name, exists := product["name"]
		if !exists || name == "" {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Product name is required"})
		}

		data, err := json.Marshal(product)
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": "Failed to process product data"})
		}

		_, err = db.Exec("INSERT INTO products (name, data) VALUES (?, ?)", name, string(data))
		if err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Failed to add product, possibly duplicate name"})
		}

		return c.Status(fiber.StatusCreated).JSON(fiber.Map{"message": "Product successfully added"})
	})

	// Route to download product data
	app.Get("/download", func(c *fiber.Ctx) error {
		name := c.Query("name")
		if name == "" {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Product name is required"})
		}

		var data string
		err := db.QueryRow("SELECT data FROM products WHERE name = ?", name).Scan(&data)
		if err == sql.ErrNoRows {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Product not found"})
		} else if err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": "Failed to retrieve product data"})
		}

		return c.JSON(fiber.Map{"data": data})
	})

	// Route to upload product data
	app.Post("/upload", func(c *fiber.Ctx) error {
		var payload struct {
			Name string `json:"name"`
			Data string `json:"data"`
		}
		if err := c.BodyParser(&payload); err != nil {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Invalid input"})
		}

		if payload.Name == "" || payload.Data == "" {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Both name and data are required"})
		}

		_, err := db.Exec("UPDATE products SET data = ? WHERE name = ?", payload.Data, payload.Name)
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": "Failed to update product data"})
		}

		return c.JSON(fiber.Map{"message": "Product successfully updated"})
	})

	// Route to search for products
	app.Get("/search", func(c *fiber.Ctx) error {
		query := c.Query("query")
		if query == "" {
			return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Search query is required"})
		}

		rows, err := db.Query("SELECT data FROM products WHERE name LIKE ? OR data LIKE ?", "%"+query+"%", "%"+query+"%")
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": "Failed to search products"})
		}
		defer rows.Close()

		var results []map[string]string
		for rows.Next() {
			var data string
			if err := rows.Scan(&data); err != nil {
				return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": "Failed to process search results"})
			}

			var product map[string]string
			if err := json.Unmarshal([]byte(data), &product); err != nil {
				return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": "Failed to parse product data"})
			}
			results = append(results, product)
		}

		return c.JSON(fiber.Map{"results": results})
	})

	// Start the server
	log.Println("Server is running on http://0.0.0.0:5000")
	if err := app.Listen("0.0.0.0:5000"); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}

