import (
	"database/sql"
	"log"
	"net/http"
	"os"

	"github.com/gin-gonic/gin"
	_ "github.com/mattn/go-sqlite3"
)

func main() {
	// Initialize Gin router
	router := gin.Default()

	// Initialize SQLite database
	db, err := sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// Create tables if they don't exist
	createTableQuery := `
	CREATE TABLE IF NOT EXISTS card_phone_associations (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		credit_card TEXT NOT NULL,
		phone TEXT NOT NULL
	);
	`
	_, err = db.Exec(createTableQuery)
	if err != nil {
		log.Fatalf("Failed to create table: %v", err)
	}

	// Route to associate a credit card with a phone number
	router.POST("/associate_card", func(c *gin.Context) {
		var requestBody struct {
			CreditCard string `json:"credit_card"`
			Phone      string `json:"phone"`
		}

		// Parse JSON request body
		if err := c.ShouldBindJSON(&requestBody); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid request"})
			return
		}

		// Validate input
		if requestBody.CreditCard == "" || requestBody.Phone == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Credit card and phone number are required"})
			return
		}

		// Insert association into the database
		query := "INSERT INTO card_phone_associations (credit_card, phone) VALUES (?, ?)"
		_, err := db.Exec(query, requestBody.CreditCard, requestBody.Phone)
		if err != nil {
			log.Printf("Failed to insert association: %v", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to create association"})
			return
		}

		c.JSON(http.StatusCreated, gin.H{"message": "Association created successfully"})
	})

	// Route to retrieve credit cards associated with a set of phone numbers
	router.POST("/retrieve_cards", func(c *gin.Context) {
		var requestBody struct {
			PhoneNumbers []string `json:"phone_numbers"`
		}

		// Parse JSON request body
		if err := c.ShouldBindJSON(&requestBody); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid request"})
			return
		}

		// Validate input
		if len(requestBody.PhoneNumbers) == 0 {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Phone numbers are required"})
			return
		}

		// Build query to find credit cards associated with all given phone numbers
		query := `
		SELECT credit_card
		FROM card_phone_associations
		WHERE phone IN (`
		placeholders := ""
		args := []interface{}{}
		for i, phone := range requestBody.PhoneNumbers {
			if i > 0 {
				placeholders += ", "
			}
			placeholders += "?"
			args = append(args, phone)
		}
		query += placeholders + `)
		GROUP BY credit_card
		HAVING COUNT(DISTINCT phone) = ?`
		args = append(args, len(requestBody.PhoneNumbers))

		// Execute query
		rows, err := db.Query(query, args...)
		if err != nil {
			log.Printf("Failed to retrieve cards: %v", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to retrieve cards"})
			return
		}
		defer rows.Close()

		// Collect results
		var cardNumbers []string
		for rows.Next() {
			var cardNumber string
			if err := rows.Scan(&cardNumber); err != nil {
				log.Printf("Failed to scan row: %v", err)
				c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to retrieve cards"})
				return
			}
			cardNumbers = append(cardNumbers, cardNumber)
		}

		// Check if no cards were found
		if len(cardNumbers) == 0 {
			c.JSON(http.StatusNotFound, gin.H{"error": "No cards found"})
			return
		}

		// Return results
		c.JSON(http.StatusOK, gin.H{"card_numbers": cardNumbers})
	})

	// Start the server
	port := "5000"
	if os.Getenv("PORT") != "" {
		port = os.Getenv("PORT")
	}
	router.Run("0.0.0.0:" + port)
}

package main

import (
	"fmt"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/gin-gonic/gin"
)

const uploadDir = "./uploads"
const outputDir = "./frames"

func main() {
	// Create necessary directories
	if err := os.MkdirAll(uploadDir, 0755); err != nil {
		fmt.Printf("Error creating upload directory: %v\n", err)
		return
	}
	if err := os.MkdirAll(outputDir, 0755); err != nil {
		fmt.Printf("Error creating output directory: %v\n", err)
		return
	}

	// Initialize Gin router
	router := gin.Default()

	// Define the /extract endpoint
	router.POST("/extract", func(c *gin.Context) {
		// Parse multipart form data
		videoFile, err := c.FormFile("video")
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Video file is required"})
			return
		}

		frameNumberStr := c.PostForm("frameNumber")
		if frameNumberStr == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Frame number is required"})
			return
		}

		frameNumber, err := strconv.Atoi(frameNumberStr)
		if err != nil || frameNumber < 0 {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid frame number"})
			return
		}

		videoFileName := c.PostForm("videoFileName")
		if videoFileName == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Video file name is required"})
			return
		}

		// Sanitize the video file name
		videoFileName = filepath.Base(videoFileName)
		if strings.Contains(videoFileName, "..") || strings.Contains(videoFileName, "/") {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid video file name"})
			return
		}

		// Save the uploaded video file
		videoPath := filepath.Join(uploadDir, videoFileName)
		if err := c.SaveUploadedFile(videoFile, videoPath); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to save video file"})
			return
		}

		// Generate the output frame file path
		outputFramePath := filepath.Join(outputDir, fmt.Sprintf("frame_%d.png", frameNumber))

		// Use ffmpeg to extract the frame
		cmd := exec.Command("ffmpeg", "-i", videoPath, "-vf", fmt.Sprintf("select=eq(n\\,%d)", frameNumber), "-vframes", "1", outputFramePath)
		if err := cmd.Run(); err != nil {
			c.JSON(http.StatusNotFound, gin.H{"error": fmt.Sprintf("Frame at index %d could not be found", frameNumber)})
			return
		}

		// Serve the extracted frame
		c.File(outputFramePath)
	})

	// Start the server
	router.Run("0.0.0.0:5000")
}

package main

import (
	"bytes"
	"fmt"
	"image"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/gin-gonic/gin"
)

const storageDir = "./uploads"

func sanitizePath(input string) (string, error) {
	absPath, err := filepath.Abs(input)
	if err != nil {
		return "", err
	}
	if !strings.HasPrefix(absPath, storageDir) {
		return "", fmt.Errorf("invalid path")
	}
	return absPath, nil
}

func validateTargetSize(size string) (string, error) {
	parts := strings.Split(size, "x")
	if len(parts) != 2 {
		return "", fmt.Errorf("invalid target size format")
	}
	width, err := strconv.Atoi(parts[0])
	if err != nil || width <= 0 {
		return "", fmt.Errorf("invalid width in target size")
	}
	height, err := strconv.Atoi(parts[1])
	if err != nil || height <= 0 {
		return "", fmt.Errorf("invalid height in target size")
	}
	return fmt.Sprintf("%dx%d", width, height), nil
}

func validateDelay(delay int) int {
	if delay < 1 {
		return 10 // Default delay
	}
	return delay
}

func main() {
	// Ensure storage directory exists
	if err := os.MkdirAll(storageDir, 0755); err != nil {
		fmt.Printf("Failed to create storage directory: %v\n", err)
		return
	}

	router := gin.Default()

	router.POST("/create-gif", func(c *gin.Context) {
		form, err := c.MultipartForm()
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid form data"})
			return
		}

		// Validate and process images
		files := form.File["images"]
		if len(files) == 0 {
			c.JSON(http.StatusBadRequest, gin.H{"error": "No images provided"})
			return
		}

		var imagePaths []string
		for _, file := range files {
			filePath := filepath.Join(storageDir, filepath.Base(file.Filename))
			safePath, err := sanitizePath(filePath)
			if err != nil {
				c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid file path"})
				return
			}
			if err := c.SaveUploadedFile(file, safePath); err != nil {
				c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to save file"})
				return
			}
			imagePaths = append(imagePaths, safePath)
		}

		// Validate target size
		targetSize := c.PostForm("targetSize")
		validSize, err := validateTargetSize(targetSize)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid target size"})
			return
		}

		// Validate delay
		delayStr := c.PostForm("delay")
		delay := 10 // Default delay
		if delayStr != "" {
			delay, err = strconv.Atoi(delayStr)
			if err != nil {
				c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid delay value"})
				return
			}
		}
		delay = validateDelay(delay)

		// Validate appendReverted
		appendReverted := c.PostForm("appendReverted") == "true"

		// Prepare command arguments
		var args []string
		for _, img := range imagePaths {
			args = append(args, img)
		}
		if appendReverted {
			for i := len(imagePaths) - 1; i >= 0; i-- {
				args = append(args, imagePaths[i])
			}
		}
		args = append(args, "-resize", validSize, "-delay", strconv.Itoa(delay), "-loop", "0", "gif:-")

		// Execute ImageMagick command
		cmd := exec.Command("convert", args...)
		var out bytes.Buffer
		cmd.Stdout = &out
		cmd.Stderr = &out
		if err := cmd.Run(); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to create GIF", "details": out.String()})
			return
		}

		// Return the generated GIF
		c.Data(http.StatusOK, "image/gif", out.Bytes())
	})

	router.Run("0.0.0.0:5000")
}

package main

import (
	"bufio"
	"log"
	"net/http"
	"os"
	"sync"

	"github.com/gin-gonic/gin"
	"html"
)

var (
	logFileName = "logs.txt"
	mutex       sync.Mutex
)

func main() {
	// Ensure the log file exists
	file, err := os.OpenFile(logFileName, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
	if err != nil {
		log.Fatalf("Failed to create or open log file: %v", err)
	}
	file.Close()

	// Initialize Gin router
	router := gin.Default()

	// POST /log - Log a message
	router.POST("/log", func(c *gin.Context) {
		var requestBody struct {
			Message string `json:"message"`
		}

		// Bind JSON input and validate
		if err := c.ShouldBindJSON(&requestBody); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
			return
		}

		// Sanitize the input message
		sanitizedMessage := html.EscapeString(requestBody.Message)

		// Write the sanitized message to the log file
		mutex.Lock()
		defer mutex.Unlock()
		file, err := os.OpenFile(logFileName, os.O_WRONLY|os.O_APPEND, 0644)
		if err != nil {
			log.Printf("Failed to open log file: %v", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to write log"})
			return
		}
		defer file.Close()

		if _, err := file.WriteString(sanitizedMessage + "\n"); err != nil {
			log.Printf("Failed to write to log file: %v", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to write log"})
			return
		}

		c.JSON(http.StatusOK, gin.H{"message": "Log message successful"})
	})

	// GET /logs - Retrieve all logged messages
	router.GET("/logs", func(c *gin.Context) {
		mutex.Lock()
		defer mutex.Unlock()
		file, err := os.Open(logFileName)
		if err != nil {
			log.Printf("Failed to open log file: %v", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to retrieve logs"})
			return
		}
		defer file.Close()

		// Read all lines from the log file
		var logs []string
		scanner := bufio.NewScanner(file)
		for scanner.Scan() {
			logs = append(logs, scanner.Text())
		}
		if err := scanner.Err(); err != nil {
			log.Printf("Failed to read log file: %v", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to retrieve logs"})
			return
		}

		// Return logs as plain text
		c.Data(http.StatusOK, "text/plain; charset=utf-8", []byte(html.EscapeString(string(joinLogs(logs)))))
	})

	// Start the server
	router.Run("0.0.0.0:5000")
}

// joinLogs safely concatenates log lines with newlines
func joinLogs(logs []string) string {
	result := ""
	for _, log := range logs {
		result += log + "\n"
	}
	return result
}

package main

import (
	"fmt"
	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"io"
	"net/http"
	"os"
	"path/filepath"
)

const (
	StorageDir = "./uploads"
)

func main() {
	// Ensure the storage directory exists
	if err := os.MkdirAll(StorageDir, 0755); err != nil {
		fmt.Printf("Failed to create storage directory: %v\n", err)
		return
	}

	r := gin.Default()

	// Route for uploading images
	r.POST("/upload", func(c *gin.Context) {
		file, err := c.FormFile("file")
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid file input"})
			return
		}

		// Sanitize and validate the file name
		filename := filepath.Base(file.Filename)
		if filename == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid file name"})
			return
		}

		// Generate a unique ID for the file
		imageID := uuid.New().String()
		filePath := filepath.Join(StorageDir, imageID+"_"+filename)

		// Save the file securely
		if err := c.SaveUploadedFile(file, filePath); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to save file"})
			return
		}

		// Return the shareable link
		c.JSON(http.StatusOK, gin.H{"id": imageID})
	})

	// Route for viewing images
	r.GET("/images/:imageId", func(c *gin.Context) {
		imageID := c.Param("imageId")

		// Validate the image ID
		if imageID == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid image ID"})
			return
		}

		// Search for the file in the storage directory
		var foundFile string
		err := filepath.Walk(StorageDir, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}
			if !info.IsDir() && filepath.Base(path)[:len(imageID)] == imageID {
				foundFile = path
				return io.EOF // Stop walking once the file is found
			}
			return nil
		})
		if err != nil && err != io.EOF {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to search for file"})
			return
		}

		// If no file is found, return 404
		if foundFile == "" {
			c.JSON(http.StatusNotFound, gin.H{"error": "Image not found"})
			return
		}

		// Serve the file with the correct content type
		c.File(foundFile)
	})

	// Start the server
	if err := r.Run("0.0.0.0:5000"); err != nil {
		fmt.Printf("Failed to start server: %v\n", err)
	}
}

