import (
	"database/sql"
	"log"
	"net/http"
	"os"

	"github.com/gin-gonic/gin"
	_ "github.com/mattn/go-sqlite3"
)

func main() {
	// Initialize Gin router
	router := gin.Default()

	// Initialize SQLite database
	db, err := sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// Create users table if it doesn't exist
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS users (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			email TEXT NOT NULL UNIQUE,
			password TEXT NOT NULL,
			name TEXT NOT NULL
		)
	`)
	if err != nil {
		log.Fatalf("Failed to create users table: %v", err)
	}

	// Routes
	router.POST("/login", func(c *gin.Context) {
		var requestBody struct {
			Email    string `json:"email" binding:"required,email"`
			Password string `json:"password" binding:"required"`
		}

		if err := c.ShouldBindJSON(&requestBody); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"message": "Invalid request body"})
			return
		}

		var storedPassword string
		err := db.QueryRow("SELECT password FROM users WHERE email = ?", requestBody.Email).Scan(&storedPassword)
		if err == sql.ErrNoRows {
			c.JSON(http.StatusUnauthorized, gin.H{"message": "Invalid email or password"})
			return
		} else if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"message": "Internal server error"})
			return
		}

		if storedPassword != requestBody.Password {
			c.JSON(http.StatusUnauthorized, gin.H{"message": "Invalid email or password"})
			return
		}

		// Generate a dummy token (in a real-world app, use a proper JWT library)
		token := "jwt-token-abc123"

		c.JSON(http.StatusOK, gin.H{
			"token":   token,
			"message": "Login successful",
		})
	})

	router.POST("/register", func(c *gin.Context) {
		var requestBody struct {
			Email    string `json:"email" binding:"required,email"`
			Password string `json:"password" binding:"required"`
			Name     string `json:"name" binding:"required"`
		}

		if err := c.ShouldBindJSON(&requestBody); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"message": "Invalid request body"})
			return
		}

		_, err := db.Exec("INSERT INTO users (email, password, name) VALUES (?, ?, ?)", requestBody.Email, requestBody.Password, requestBody.Name)
		if err != nil {
			if sqliteErr, ok := err.(sqlite3.Error); ok && sqliteErr.Code == sqlite3.ErrConstraint {
				c.JSON(http.StatusBadRequest, gin.H{"message": "Email already in use"})
			} else {
				c.JSON(http.StatusInternalServerError, gin.H{"message": "Internal server error"})
			}
			return
		}

		c.JSON(http.StatusCreated, gin.H{"message": "Registration successful"})
	})

	// Start the server
	port := "5000"
	if os.Getenv("PORT") != "" {
		port = os.Getenv("PORT")
	}
	router.Run("0.0.0.0:" + port)
}

package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"os/exec"
	"regexp"
	"strconv"
	"strings"

	"github.com/gin-gonic/gin"
)

type ProcessFilter struct {
	FilterFlags   string `json:"filter_flags"`
	CommandRegex  string `json:"command_regex" binding:"required"`
}

type Process struct {
	ProcessID     int    `json:"processId"`
	ProcessString string `json:"processString"`
}

type ErrorResponse struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

func main() {
	r := gin.Default()

	r.POST("/monitor/commands", func(c *gin.Context) {
		var filter ProcessFilter
		if err := c.ShouldBindJSON(&filter); err != nil {
			c.JSON(http.StatusBadRequest, ErrorResponse{
				Code:    http.StatusBadRequest,
				Message: "Invalid request body: " + err.Error(),
			})
			return
		}

		// Validate the command_regex to ensure it's a valid regex
		_, err := regexp.Compile(filter.CommandRegex)
		if err != nil {
			c.JSON(http.StatusBadRequest, ErrorResponse{
				Code:    http.StatusBadRequest,
				Message: "Invalid regular expression: " + err.Error(),
			})
			return
		}

		// Construct the ps command
		psArgs := []string{"-eo", "pid,command"}
		if filter.FilterFlags != "" {
			psArgs = append(psArgs, strings.Fields(filter.FilterFlags)...)
		}

		// Execute the ps command
		cmd := exec.Command("ps", psArgs...)
		var out bytes.Buffer
		cmd.Stdout = &out
		if err := cmd.Run(); err != nil {
			c.JSON(http.StatusInternalServerError, ErrorResponse{
				Code:    http.StatusInternalServerError,
				Message: "Failed to execute ps command: " + err.Error(),
			})
			return
		}

		// Parse the output of the ps command
		lines := strings.Split(out.String(), "\n")
		var processes []Process
		regex := regexp.MustCompile(filter.CommandRegex)

		for _, line := range lines {
			fields := strings.Fields(line)
			if len(fields) < 2 {
				continue
			}

			// Extract PID and command
			pid, err := strconv.Atoi(fields[0])
			if err != nil {
				continue
			}
			command := strings.Join(fields[1:], " ")

			// Match the command against the regex
			if regex.MatchString(command) {
				processes = append(processes, Process{
					ProcessID:     pid,
					ProcessString: command,
				})
			}
		}

		// Return the filtered processes
		c.JSON(http.StatusOK, processes)
	})

	r.Run("0.0.0.0:5000")
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/gin-gonic/gin"
)

const uploadDir = "./uploads"
const outputDir = "./output"

func main() {
	// Ensure upload and output directories exist
	if err := os.MkdirAll(uploadDir, 0755); err != nil {
		fmt.Printf("Error creating upload directory: %v\n", err)
		return
	}
	if err := os.MkdirAll(outputDir, 0755); err != nil {
		fmt.Printf("Error creating output directory: %v\n", err)
		return
	}

	// Initialize Gin router
	router := gin.Default()

	// Define the /concatenate endpoint
	router.POST("/concatenate", func(c *gin.Context) {
		// Parse multipart form
		form, err := c.MultipartForm()
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input or missing files."})
			return
		}

		files := form.File["files"]
		if len(files) == 0 {
			c.JSON(http.StatusBadRequest, gin.H{"error": "No files provided."})
			return
		}

		// Validate and save uploaded files
		var savedFiles []string
		for _, file := range files {
			if !strings.HasSuffix(file.Filename, ".pdf") {
				c.JSON(http.StatusBadRequest, gin.H{"error": "Only PDF files are allowed."})
				return
			}

			// Sanitize filename
			safeFilename := filepath.Base(file.Filename)
			filePath := filepath.Join(uploadDir, safeFilename)

			// Save the file
			if err := c.SaveUploadedFile(file, filePath); err != nil {
				c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to save file."})
				return
			}

			savedFiles = append(savedFiles, filePath)
		}

		// Generate a unique output filename
		outputFile := filepath.Join(outputDir, "concatenated.pdf")

		// Concatenate files using pdfunite
		cmdArgs := append(savedFiles, outputFile)
		cmd := exec.Command("pdfunite", cmdArgs...)
		var stderr bytes.Buffer
		cmd.Stderr = &stderr

		if err := cmd.Run(); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to concatenate PDF files.", "details": stderr.String()})
			return
		}

		// Serve the concatenated PDF file
		c.Header("Content-Type", "application/pdf")
		c.Header("Content-Disposition", "attachment; filename=concatenated.pdf")
		c.File(outputFile)

		// Clean up temporary files
		for _, file := range savedFiles {
			_ = os.Remove(file)
		}
		_ = os.Remove(outputFile)
	})

	// Start the server
	router.Run("0.0.0.0:5000")
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"

	"github.com/gin-gonic/gin"
)

const (
	uploadDir = "./uploads"
)

func main() {
	// Create the upload directory if it doesn't exist
	if err := os.MkdirAll(uploadDir, 0755); err != nil {
		fmt.Printf("Failed to create upload directory: %v\n", err)
		return
	}

	// Initialize the Gin router
	router := gin.Default()

	// Define the /convert endpoint
	router.POST("/convert", func(c *gin.Context) {
		// Parse the uploaded file
		file, err := c.FormFile("file")
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Missing or invalid file"})
			return
		}

		// Sanitize the file name
		filename := filepath.Base(file.Filename)
		if filename == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid file name"})
			return
		}

		// Save the uploaded file to a temporary location
		tempFilePath := filepath.Join(uploadDir, filename)
		if err := c.SaveUploadedFile(file, tempFilePath); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to save file"})
			return
		}
		defer os.Remove(tempFilePath) // Ensure the file is removed after processing

		// Validate that the file is a PDF
		if filepath.Ext(tempFilePath) != ".pdf" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Uploaded file is not a PDF"})
			return
		}

		// Extract text from the PDF using the `pdftotext` utility
		text, err := extractTextFromPDF(tempFilePath)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to extract text from PDF"})
			return
		}

		// Return the extracted text as plain text
		c.Data(http.StatusOK, "text/plain; charset=utf-8", []byte(text))
	})

	// Start the server on 0.0.0.0:5000
	router.Run("0.0.0.0:5000")
}

// extractTextFromPDF extracts text from a PDF file using the `pdftotext` utility
func extractTextFromPDF(pdfPath string) (string, error) {
	// Use a temporary file to store the extracted text
	tempTextFile := pdfPath + ".txt"
	defer os.Remove(tempTextFile) // Ensure the temporary text file is removed

	// Execute the `pdftotext` command
	cmd := exec.Command("pdftotext", pdfPath, tempTextFile)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("pdftotext error: %v, details: %s", err, stderr.String())
	}

	// Read the extracted text from the temporary file
	text, err := os.ReadFile(tempTextFile)
	if err != nil {
		return "", fmt.Errorf("failed to read extracted text: %v", err)
	}

	return string(text), nil
}

package main

import (
	"database/sql"
	"encoding/json"
	"log"
	"net/http"
	"os"

	"github.com/gin-gonic/gin"
	_ "github.com/mattn/go-sqlite3"
)

func main() {
	// Initialize Gin router
	router := gin.Default()

	// Initialize SQLite database
	db, err := sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// Create the products table if it doesn't exist
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS products (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			name TEXT NOT NULL UNIQUE,
			data TEXT NOT NULL
		)
	`)
	if err != nil {
		log.Fatalf("Failed to create table: %v", err)
	}

	// Route to add a new product
	router.POST("/add", func(c *gin.Context) {
		var product map[string]string
		if err := c.ShouldBindJSON(&product); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
			return
		}

		name, exists := product["name"]
		if !exists || name == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Product name is required"})
			return
		}

		data, err := json.Marshal(product)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to process product data"})
			return
		}

		_, err = db.Exec("INSERT INTO products (name, data) VALUES (?, ?)", name, string(data))
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Failed to add product, possibly duplicate name"})
			return
		}

		c.JSON(http.StatusCreated, gin.H{"message": "Product successfully added"})
	})

	// Route to download product data
	router.GET("/download", func(c *gin.Context) {
		name := c.Query("name")
		if name == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Product name is required"})
			return
		}

		var data string
		err := db.QueryRow("SELECT data FROM products WHERE name = ?", name).Scan(&data)
		if err == sql.ErrNoRows {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Product not found"})
			return
		} else if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to retrieve product data"})
			return
		}

		c.JSON(http.StatusOK, gin.H{"data": data})
	})

	// Route to upload product data
	router.POST("/upload", func(c *gin.Context) {
		var payload struct {
			Name string `json:"name"`
			Data string `json:"data"`
		}
		if err := c.ShouldBindJSON(&payload); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
			return
		}

		if payload.Name == "" || payload.Data == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Both name and data are required"})
			return
		}

		_, err := db.Exec("UPDATE products SET data = ? WHERE name = ?", payload.Data, payload.Name)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to update product data"})
			return
		}

		c.JSON(http.StatusOK, gin.H{"message": "Product successfully updated"})
	})

	// Route to search for products
	router.GET("/search", func(c *gin.Context) {
		query := c.Query("query")
		if query == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Search query is required"})
			return
		}

		rows, err := db.Query("SELECT data FROM products WHERE name LIKE ? OR data LIKE ?", "%"+query+"%", "%"+query+"%")
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to search for products"})
			return
		}
		defer rows.Close()

		var results []map[string]string
		for rows.Next() {
			var data string
			if err := rows.Scan(&data); err != nil {
				c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to process search results"})
				return
			}

			var product map[string]string
			if err := json.Unmarshal([]byte(data), &product); err != nil {
				c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to parse product data"})
				return
			}

			results = append(results, product)
		}

		c.JSON(http.StatusOK, gin.H{"results": results})
	})

	// Start the server
	port := "5000"
	if os.Getenv("PORT") != "" {
		port = os.Getenv("PORT")
	}
	router.Run("0.0.0.0:" + port)
}

