)

func main() {
	// Initialize Gin router
	router := gin.Default()

	// Initialize SQLite database
	db, err := sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// Create tables if they don't exist
	createTableQuery := `
	CREATE TABLE IF NOT EXISTS products (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		product_name TEXT NOT NULL,
		tags TEXT NOT NULL
	);`
	_, err = db.Exec(createTableQuery)
	if err != nil {
		log.Fatalf("Failed to create table: %v", err)
	}

	// GET /recommender - Get products by tags
	router.GET("/recommender", func(c *gin.Context) {
		tags := c.Query("tags")
		if tags == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "tags query parameter is required"})
			return
		}

		// Split tags into a slice
		tagList := strings.Split(tags, ",")

		// Construct SQL query with placeholders
		query := `SELECT product_name, tags FROM products WHERE `
		conditions := make([]string, len(tagList))
		args := make([]interface{}, len(tagList))
		for i, tag := range tagList {
			conditions[i] = "tags LIKE ?"
			args[i] = "%" + strings.TrimSpace(tag) + "%"
		}
		query += strings.Join(conditions, " OR ")

		// Execute query
		rows, err := db.Query(query, args...)
		if err != nil {
			log.Printf("Failed to execute query: %v", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Internal server error"})
			return
		}
		defer rows.Close()

		// Collect results
		var results []string
		for rows.Next() {
			var productName, tags string
			if err := rows.Scan(&productName, &tags); err != nil {
				log.Printf("Failed to scan row: %v", err)
				c.JSON(http.StatusInternalServerError, gin.H{"error": "Internal server error"})
				return
			}
			results = append(results, productName+" (Tags: "+tags+")")
		}

		// Return results as HTML
		c.Data(http.StatusOK, "text/html", []byte(strings.Join(results, "<br>")))
	})

	// POST /recommender - Add a new product
	router.POST("/recommender", func(c *gin.Context) {
		var requestBody struct {
			ProductName string   `json:"product_name" binding:"required"`
			Tags        []string `json:"tags" binding:"required"`
		}

		// Bind JSON input
		if err := c.ShouldBindJSON(&requestBody); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
			return
		}

		// Insert product into database
		insertQuery := `INSERT INTO products (product_name, tags) VALUES (?, ?)`
		_, err := db.Exec(insertQuery, requestBody.ProductName, strings.Join(requestBody.Tags, ","))
		if err != nil {
			log.Printf("Failed to insert product: %v", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Internal server error"})
			return
		}

		c.JSON(http.StatusOK, gin.H{"message": "Product added successfully"})
	})

	// Start the server
	port := "5000"
	if os.Getenv("PORT") != "" {
		port = os.Getenv("PORT")
	}
	router.Run("0.0.0.0:" + port)
}

package main

import (
	"database/sql"
	"log"
	"net/http"

	"github.com/gin-gonic/gin"
	_ "github.com/mattn/go-sqlite3"
	"github.com/google/uuid"
)

const databaseFile = "db.sqlite3"

func main() {
	// Initialize the database
	db, err := sql.Open("sqlite3", databaseFile)
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// Create tables if they don't exist
	createTables(db)

	// Initialize the Gin router
	router := gin.Default()

	// Routes
	router.GET("/recipes", func(c *gin.Context) {
		getRecipesHandler(c, db)
	})
	router.POST("/recipes/upload", func(c *gin.Context) {
		uploadRecipeHandler(c, db)
	})
	router.GET("/recipes/:recipeId", func(c *gin.Context) {
		getRecipeHandler(c, db)
	})
	router.POST("/recipes/:recipeId/comments", func(c *gin.Context) {
		addCommentHandler(c, db)
	})
	router.POST("/recipes/:recipeId/ratings", func(c *gin.Context) {
		addRatingHandler(c, db)
	})

	// Start the server
	log.Println("Starting server on 0.0.0.0:5000")
	if err := router.Run("0.0.0.0:5000"); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}

func createTables(db *sql.DB) {
	_, err := db.Exec(`
		CREATE TABLE IF NOT EXISTS recipes (
			id TEXT PRIMARY KEY,
			title TEXT NOT NULL,
			ingredients TEXT NOT NULL,
			instructions TEXT NOT NULL
		);
		CREATE TABLE IF NOT EXISTS comments (
			id TEXT PRIMARY KEY,
			recipe_id TEXT NOT NULL,
			comment TEXT NOT NULL,
			FOREIGN KEY (recipe_id) REFERENCES recipes(id)
		);
		CREATE TABLE IF NOT EXISTS ratings (
			id TEXT PRIMARY KEY,
			recipe_id TEXT NOT NULL,
			rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
			FOREIGN KEY (recipe_id) REFERENCES recipes(id)
		);
	`)
	if err != nil {
		log.Fatalf("Failed to create tables: %v", err)
	}
}

func getRecipesHandler(c *gin.Context, db *sql.DB) {
	rows, err := db.Query("SELECT id, title FROM recipes")
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to retrieve recipes"})
		return
	}
	defer rows.Close()

	var recipes []gin.H
	for rows.Next() {
		var id, title string
		if err := rows.Scan(&id, &title); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to parse recipes"})
			return
		}
		recipes = append(recipes, gin.H{"id": id, "title": title})
	}

	c.JSON(http.StatusOK, recipes)
}

func uploadRecipeHandler(c *gin.Context, db *sql.DB) {
	var input struct {
		Title        string   `json:"title" binding:"required"`
		Ingredients  []string `json:"ingredients" binding:"required"`
		Instructions string   `json:"instructions" binding:"required"`
	}

	if err := c.ShouldBindJSON(&input); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
		return
	}

	id := uuid.New().String()
	ingredients := ""
	for i, ingredient := range input.Ingredients {
		if i > 0 {
			ingredients += ", "
		}
		ingredients += ingredient
	}

	_, err := db.Exec("INSERT INTO recipes (id, title, ingredients, instructions) VALUES (?, ?, ?, ?)",
		id, input.Title, ingredients, input.Instructions)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to upload recipe"})
		return
	}

	c.JSON(http.StatusCreated, gin.H{"id": id, "title": input.Title})
}

func getRecipeHandler(c *gin.Context, db *sql.DB) {
	recipeId := c.Param("recipeId")

	row := db.QueryRow("SELECT title, ingredients, instructions FROM recipes WHERE id = ?", recipeId)
	var title, ingredients, instructions string
	if err := row.Scan(&title, &ingredients, &instructions); err != nil {
		if err == sql.ErrNoRows {
			c.JSON(http.StatusNotFound, gin.H{"error": "Recipe not found"})
		} else {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to retrieve recipe"})
		}
		return
	}

	c.JSON(http.StatusOK, gin.H{
		"title":        title,
		"ingredients":  ingredients,
		"instructions": instructions,
	})
}

func addCommentHandler(c *gin.Context, db *sql.DB) {
	recipeId := c.Param("recipeId")
	var input struct {
		Comment string `json:"comment" binding:"required"`
	}

	if err := c.ShouldBindJSON(&input); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
		return
	}

	id := uuid.New().String()
	_, err := db.Exec("INSERT INTO comments (id, recipe_id, comment) VALUES (?, ?, ?)", id, recipeId, input.Comment)
	if err != nil {
