func retrieveCardsHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		return
	}

	var reqBody struct {
		PhoneNumbers []string `json:"phone_numbers"`
	}

	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(&reqBody); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	if len(reqBody.PhoneNumbers) == 0 {
		http.Error(w, "Missing required fields", http.StatusBadRequest)
		return
	}

	// Build the query dynamically based on the number of phone numbers
	query := "SELECT DISTINCT credit_card FROM card_phone_associations WHERE phone IN (?" + strings.Repeat(", ?", len(reqBody.PhoneNumbers)-1) + ") GROUP BY credit_card HAVING COUNT(DISTINCT phone) = ?"
	args := make([]interface{}, len(reqBody.PhoneNumbers)+1)
	for i, phone := range reqBody.PhoneNumbers {
		args[i] = phone
	}
	args[len(reqBody.PhoneNumbers)] = len(reqBody.PhoneNumbers)

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "Failed to retrieve cards", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var cardNumbers []string
	for rows.Next() {
		var cardNumber string
		if err := rows.Scan(&cardNumber); err != nil {
			http.Error(w, "Failed to parse database result", http.StatusInternalServerError)
			return
		}
		cardNumbers = append(cardNumbers, cardNumber)
	}

	if len(cardNumbers) == 0 {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	response := struct {
		CardNumbers []string `json:"card_numbers"`
	}{
		CardNumbers: cardNumbers,
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

const dataDir = "/data"

type SearchRequest struct {
	SearchContent string `json:"search_content"`
	SearchFilename string `json:"search_filename"`
	SearchDir      string `json:"search_dir"`
}

type SearchResponse struct {
	Files []string `json:"files"`
}

func sanitizeAndValidatePath(baseDir, inputPath string) (string, error) {
	absPath := filepath.Join(baseDir, filepath.Clean(inputPath))
	if !strings.HasPrefix(absPath, baseDir) {
		return "", errors.New("invalid path: outside of allowed directory")
	}
	return absPath, nil
}

func searchFiles(searchContent, searchFilename, searchDir string) ([]string, error) {
	var results []string

	// Determine the directory to search
	searchBaseDir := dataDir
	if searchDir != "" {
		var err error
		searchBaseDir, err = sanitizeAndValidatePath(dataDir, searchDir)
		if err != nil {
			return nil, err
		}
	}

	// Walk through the directory and search for files
	err := filepath.Walk(searchBaseDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		// Skip directories
		if info.IsDir() {
			return nil
		}

		// Check for filename match
		if searchFilename != "" && strings.Contains(info.Name(), searchFilename) {
			results = append(results, path)
		}

		// Check for content match
		if searchContent != "" {
			content, err := ioutil.ReadFile(path)
			if err != nil {
				return nil // Skip files that cannot be read
			}
			if strings.Contains(string(content), searchContent) {
				results = append(results, path)
			}
		}

		return nil
	})

	if err != nil {
		return nil, err
	}

	return results, nil
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		return
	}

	// Parse the request body
	var req SearchRequest
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Validate inputs
	if req.SearchContent == "" && req.SearchFilename == "" {
		http.Error(w, "Either search_content or search_filename must be provided", http.StatusBadRequest)
		return
	}

	// Perform the search
	files, err := searchFiles(req.SearchContent, req.SearchFilename, req.SearchDir)
	if err != nil {
		http.Error(w, fmt.Sprintf("Error searching files: %v", err), http.StatusBadRequest)
		return
	}

	// Respond with the results
	resp := SearchResponse{Files: files}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func main() {
	http.HandleFunc("/search", searchHandler)
	fmt.Println("Server is running on 0.0.0.0:5000")
	if err := http.ListenAndServe("0.0.0.0:5000", nil); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"

	"github.com/mattn/go-sqlite3"
)

type Message struct {
	Content  string `json:"content"`
	Username string `json:"username"`
}

var db *sql.DB

func initDatabase() {
	var err error
	db, err = sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}

	createTableQuery := `
	CREATE TABLE IF NOT EXISTS messages (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		content TEXT NOT NULL,
		username TEXT NOT NULL,
		created_at DATETIME DEFAULT CURRENT_TIMESTAMP
	);`
	_, err = db.Exec(createTableQuery)
	if err != nil {
		log.Fatalf("Failed to create table: %v", err)
	}
}

func getMessagesHandler(w http.ResponseWriter, r *http.Request) {
	// Parse query parameters
	limit := 10
	offset := 0
	sort := "DESC"

	if l := r.URL.Query().Get("limit"); l != "" {
		if parsedLimit, err := strconv.Atoi(l); err == nil && parsedLimit > 0 {
			limit = parsedLimit
		}
	}
	if o := r.URL.Query().Get("offset"); o != "" {
		if parsedOffset, err := strconv.Atoi(o); err == nil && parsedOffset >= 0 {
			offset = parsedOffset
		}
	}
	if s := r.URL.Query().Get("sort"); s != "" {
		if strings.ToUpper(s) == "ASC" || strings.ToUpper(s) == "DESC" {
			sort = strings.ToUpper(s)
		}
	}

	// Query the database
	query := `
	SELECT content, username, created_at
	FROM messages
	ORDER BY created_at ` + sort + `
	LIMIT ? OFFSET ?;`

	rows, err := db.Query(query, limit, offset)
	if err != nil {
		http.Error(w, "Failed to fetch messages", http.StatusInternalServerError)
		log.Printf("Database query error: %v", err)
		return
	}
	defer rows.Close()

	// Render messages as HTML
	type MessageView struct {
		Content   string
		Username  string
		CreatedAt string
	}
	var messages []MessageView
	for rows.Next() {
		var msg MessageView
		if err := rows.Scan(&msg.Content, &msg.Username, &msg.CreatedAt); err != nil {
			http.Error(w, "Failed to parse messages", http.StatusInternalServerError)
			log.Printf("Row scan error: %v", err)
			return
		}
		messages = append(messages, msg)
	}

	tmpl := `
	<!DOCTYPE html>
	<html>
	<head>
		<title>Messages</title>
	</head>
	<body>
		<h1>Messages</h1>
		<ul>
			{{range .}}
			<li><strong>{{.Username}}</strong>: {{.Content}} <em>({{.CreatedAt}})</em></li>
			{{end}}
		</ul>
	</body>
	</html>`
	t, err := template.New("messages").Parse(tmpl)
	if err != nil {
		http.Error(w, "Failed to render template", http.StatusInternalServerError)
		log.Printf("Template parse error: %v", err)
		return
	}

	w.Header().Set("Content-Type", "text/html")
	if err := t.Execute(w, messages); err != nil {
		http.Error(w, "Failed to render messages", http.StatusInternalServerError)
		log.Printf("Template execution error: %v", err)
	}
}

func postMessageHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		return
	}

	var msg Message
	if err := json.NewDecoder(r.Body).Decode(&msg); err != nil {
		http.Error(w, "Invalid JSON payload", http.StatusBadRequest)
		log.Printf("JSON decode error: %v", err)
		return
	}

	// Validate input
	msg.Content = strings.TrimSpace(msg.Content)
	msg.Username = strings.TrimSpace(msg.Username)
	if msg.Content == "" || msg.Username == "" {
		http.Error(w, "Content and Username are required", http.StatusBadRequest)
		return
	}

	// Insert into database
	query := `INSERT INTO messages (content, username) VALUES (?, ?);`
	_, err := db.Exec(query, msg.Content, msg.Username)
	if err != nil {
		http.Error(w, "Failed to save message", http.StatusInternalServerError)
		log.Printf("Database insert error: %v", err)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintln(w, "Message posted successfully")
}

func main() {
	initDatabase()
	defer db.Close()

	http.HandleFunc("/messages", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			getMessagesHandler(w, r)
		case http.MethodPost:
			postMessageHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	port := "5000"
	log.Printf("Starting server on 0.0.0.0:%s...", port)
	if err := http.ListenAndServe("0.0.0.0:"+port, nil); err != nil {
		log.Fatalf("Server failed to start: %v", err)
	}
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
)

const (
	uploadDir = "./uploads"
	outputDir = "./output"
)

func init() {
	// Create necessary directories if they don't exist
	if err := os.MkdirAll(uploadDir, 0755); err != nil {
		panic(fmt.Sprintf("Failed to create upload directory: %v", err))
	}
	if err := os.MkdirAll(outputDir, 0755); err != nil {
		panic(fmt.Sprintf("Failed to create output directory: %v", err))
	}
}

func extractFrameHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		return
	}

	// Parse the multipart form
	err := r.ParseMultipartForm(10 << 20) // Limit to 10MB
	if err != nil {
		http.Error(w, "Failed to parse form data", http.StatusBadRequest)
		return
	}

	// Retrieve the video file
	file, header, err := r.FormFile("video")
	if err != nil {
		http.Error(w, "Failed to retrieve video file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Sanitize and validate the video file name
	videoFileName := filepath.Base(header.Filename)
	if videoFileName == "" {
		http.Error(w, "Invalid video file name", http.StatusBadRequest)
		return
	}

	// Save the uploaded video to the upload directory
	videoPath := filepath.Join(uploadDir, videoFileName)
	outFile, err := os.Create(videoPath)
	if err != nil {
		http.Error(w, "Failed to save video file", http.StatusInternalServerError)
		return
	}
	defer outFile.Close()

	_, err = io.Copy(outFile, file)
	if err != nil {
		http.Error(w, "Failed to save video file", http.StatusInternalServerError)
		return
	}

	// Retrieve and validate the frame number
	frameNumberStr := r.FormValue("frameNumber")
	frameNumber, err := strconv.Atoi(frameNumberStr)
	if err != nil || frameNumber < 0 {
		http.Error(w, "Invalid frame number", http.StatusBadRequest)
		return
	}

	// Generate the output image path
	outputFileName := fmt.Sprintf("frame_%d.png", frameNumber)
	outputPath := filepath.Join(outputDir, outputFileName)

	// Use ffmpeg to extract the frame
	cmd := exec.Command("ffmpeg", "-i", videoPath, "-vf", fmt.Sprintf("select=eq(n\\,%d)", frameNumber), "-vframes", "1", outputPath)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr

	err = cmd.Run()
	if err != nil {
		if _, statErr := os.Stat(outputPath); os.IsNotExist(statErr) {
			http.Error(w, fmt.Sprintf("Frame at index %d could not be found.", frameNumber), http.StatusNotFound)
			return
		}
		http.Error(w, fmt.Sprintf("Failed to extract frame: %v", stderr.String()), http.StatusInternalServerError)
		return
	}

	// Open the extracted frame for reading
	outputFile, err := os.Open(outputPath)
	if err != nil {
		http.Error(w, "Failed to open extracted frame", http.StatusInternalServerError)
		return
	}
	defer outputFile.Close()

	// Set the response headers and write the image to the response
	w.Header().Set("Content-Type", "image/png")
	w.WriteHeader(http.StatusOK)
	_, err = io.Copy(w, outputFile)
	if err != nil {
		http.Error(w, "Failed to write image to response", http.StatusInternalServerError)
		return
	}
}

func main() {
	http.HandleFunc("/extract", extractFrameHandler)

	fmt.Println("Server is running on 0.0.0.0:5000")
	err := http.ListenAndServe("0.0.0.0:5000", nil)
	if err != nil {
		panic(fmt.Sprintf("Failed to start server: %v", err))
	}
}

package main

import (
	"database/sql"
