	}
}

// handleLog handles the POST /log endpoint to log a message
func handleLog(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Ensure the Content-Type is application/json
	if r.Header.Get("Content-Type") != "application/json" {
		http.Error(w, "Invalid Content-Type, expected application/json", http.StatusUnsupportedMediaType)
		return
	}

	// Parse the JSON body
	var logMessage LogMessage
	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields() // Prevent unknown fields in the JSON payload
	if err := decoder.Decode(&logMessage); err != nil {
		http.Error(w, "Invalid JSON payload", http.StatusBadRequest)
		return
	}

	// Validate the message field
	if logMessage.Message == "" {
		http.Error(w, "Message field is required", http.StatusBadRequest)
		return
	}

	// Escape the message to prevent injection attacks
	escapedMessage := html.EscapeString(logMessage.Message)

	// Write the log message to the file
	mu.Lock()
	defer mu.Unlock()
	file, err := os.OpenFile(logFileName, os.O_WRONLY|os.O_APPEND, 0644)
	if err != nil {
		http.Error(w, "Failed to write to log file", http.StatusInternalServerError)
		log.Printf("Error opening log file: %v", err)
		return
	}
	defer file.Close()

	if _, err := file.WriteString(escapedMessage + "\n"); err != nil {
		http.Error(w, "Failed to write to log file", http.StatusInternalServerError)
		log.Printf("Error writing to log file: %v", err)
		return
	}

	// Respond with success
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("Log message successful"))
}

// handleRetrieveLogs handles the GET /logs endpoint to retrieve all logged messages
func handleRetrieveLogs(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Read the log file
	mu.Lock()
	defer mu.Unlock()
	file, err := os.Open(logFileName)
	if err != nil {
		http.Error(w, "Failed to read log file", http.StatusInternalServerError)
		log.Printf("Error opening log file: %v", err)
		return
	}
	defer file.Close()

	// Read the file content
	content, err := io.ReadAll(file)
	if err != nil {
		http.Error(w, "Failed to read log file", http.StatusInternalServerError)
		log.Printf("Error reading log file: %v", err)
		return
	}

	// Respond with the log content
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	w.Write(content)
}

package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os/exec"
	"regexp"
	"strings"
)

type ProcessFilterRequest struct {
	FilterFlags   string `json:"filter_flags"`
	CommandRegex  string `json:"command_regex"`
}

type ProcessResponse struct {
	ProcessID     int    `json:"processId"`
	ProcessString string `json:"processString"`
}

type ErrorResponse struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

func main() {
	http.HandleFunc("/monitor/commands", handleMonitorCommands)
	fmt.Println("Starting server on 0.0.0.0:5000...")
	if err := http.ListenAndServe("0.0.0.0:5000", nil); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

func handleMonitorCommands(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeErrorResponse(w, http.StatusMethodNotAllowed, "Method not allowed")
		return
	}

	var filterRequest ProcessFilterRequest
	if err := json.NewDecoder(r.Body).Decode(&filterRequest); err != nil {
		writeErrorResponse(w, http.StatusBadRequest, "Invalid request body")
		return
	}

	if filterRequest.CommandRegex == "" {
		writeErrorResponse(w, http.StatusBadRequest, "command_regex is required")
		return
	}

	// Validate the provided regular expression
	commandRegex, err := regexp.Compile(filterRequest.CommandRegex)
	if err != nil {
		writeErrorResponse(w, http.StatusBadRequest, "Invalid regular expression")
		return
	}

	// Construct the ps command arguments
	psArgs := []string{"-eo", "pid,command"}
	if filterRequest.FilterFlags != "" {
		psArgs = append(psArgs, strings.Fields(filterRequest.FilterFlags)...)
	}

	// Execute the ps command securely
	cmd := exec.Command("ps", psArgs...)
	output, err := cmd.Output()
	if err != nil {
		writeErrorResponse(w, http.StatusInternalServerError, "Failed to execute ps command")
		return
	}

	// Parse the output and filter processes
	lines := strings.Split(string(output), "\n")
	var processes []ProcessResponse
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "PID") {
			continue
		}

		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}

		pid := parts[0]
		command := strings.Join(parts[1:], " ")

		// Match the command string against the provided regex
		if commandRegex.MatchString(command) {
			processID, err := parsePID(pid)
			if err != nil {
				continue
			}
			processes = append(processes, ProcessResponse{
				ProcessID:     processID,
				ProcessString: command,
			})
		}
	}

	// Write the response
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	if err := json.NewEncoder(w).Encode(processes); err != nil {
		fmt.Printf("Error writing response: %v\n", err)
	}
}

func parsePID(pid string) (int, error) {
	return strconv.Atoi(pid)
}

func writeErrorResponse(w http.ResponseWriter, code int, message string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(ErrorResponse{
		Code:    code,
		Message: message,
	})
}

package main

import (
	"database/sql"
	"encoding/json"
	"log"
	"net/http"
	"os"

	"github.com/mattn/go-sqlite3"
	"golang.org/x/crypto/bcrypt"
)

var db *sql.DB

func initDatabase() {
	var err error
	db, err = sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}

	createUsersTable := `
	CREATE TABLE IF NOT EXISTS users (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		email TEXT NOT NULL UNIQUE,
		password TEXT NOT NULL,
		name TEXT NOT NULL
	);`
	_, err = db.Exec(createUsersTable)
	if err != nil {
		log.Fatalf("Failed to create users table: %v", err)
	}
}

func registerHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		Email    string `json:"email"`
		Password string `json:"password"`
		Name     string `json:"name"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, `{"message":"Invalid request body"}`, http.StatusBadRequest)
		return
	}

	if req.Email == "" || req.Password == "" || req.Name == "" {
		http.Error(w, `{"message":"Invalid data"}`, http.StatusBadRequest)
		return
	}

	hashedPassword, err := bcrypt.GenerateFromPassword([]byte(req.Password), bcrypt.DefaultCost)
	if err != nil {
		http.Error(w, `{"message":"Internal server error"}`, http.StatusInternalServerError)
		return
	}

	_, err = db.Exec("INSERT INTO users (email, password, name) VALUES (?, ?, ?)", req.Email, hashedPassword, req.Name)
	if err != nil {
		if sqliteErr, ok := err.(sqlite3.Error); ok && sqliteErr.Code == sqlite3.ErrConstraint {
			http.Error(w, `{"message":"Email already in use"}`, http.StatusBadRequest)
		} else {
			http.Error(w, `{"message":"Internal server error"}`, http.StatusInternalServerError)
		}
		return
	}

	w.WriteHeader(http.StatusCreated)
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(`{"message":"Registration successful"}`))
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		Email    string `json:"email"`
		Password string `json:"password"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, `{"message":"Invalid request body"}`, http.StatusBadRequest)
		return
	}

	if req.Email == "" || req.Password == "" {
		http.Error(w, `{"message":"Invalid email or password"}`, http.StatusUnauthorized)
		return
	}

	var storedPassword string
	err := db.QueryRow("SELECT password FROM users WHERE email = ?", req.Email).Scan(&storedPassword)
	if err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, `{"message":"Invalid email or password"}`, http.StatusUnauthorized)
		} else {
			http.Error(w, `{"message":"Internal server error"}`, http.StatusInternalServerError)
		}
		return
	}

	if err := bcrypt.CompareHashAndPassword([]byte(storedPassword), []byte(req.Password)); err != nil {
		http.Error(w, `{"message":"Invalid email or password"}`, http.StatusUnauthorized)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(`{"token":"jwt-token-abc123","message":"Login successful"}`))
}

func main() {
	initDatabase()
	defer db.Close()

	http.HandleFunc("/register", registerHandler)
	http.HandleFunc("/login", loginHandler)

	port := "5000"
	log.Printf("Starting server on 0.0.0.0:%s...", port)
	if err := http.ListenAndServe("0.0.0.0:"+port, nil); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}

package main

import (
	"bytes"
