package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

const filesRoot = "./files"

type searchResponse struct {
	Files []string `json:"files"`
}

type errorResponse struct {
	Error string `json:"error"`
}

func main() {
	http.HandleFunc("/search", searchHandler)
	fmt.Println("Starting server on 0.0.0.0:5000...")
	if err := http.ListenAndServe("0.0.0.0:5000", nil); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Parse query parameters
	regexPattern := r.URL.Query().Get("regex")
	if regexPattern == "" {
		writeErrorResponse(w, http.StatusBadRequest, "Missing required 'regex' parameter")
		return
	}

	directory := r.URL.Query().Get("directory")
	if directory == "" {
		directory = "."
	}

	recursive := r.URL.Query().Get("recursive") == "true"

	// Validate and compile regex
	regex, err := regexp.Compile(regexPattern)
	if err != nil {
		writeErrorResponse(w, http.StatusBadRequest, "Invalid regex pattern")
		return
	}

	// Construct the full directory path
	searchDir := filepath.Join(filesRoot, filepath.Clean(directory))
	if !strings.HasPrefix(searchDir, filesRoot) {
		writeErrorResponse(w, http.StatusBadRequest, "Invalid directory path")
		return
	}

	// Search for matching files
	files, err := searchFiles(searchDir, regex, recursive)
	if err != nil {
		writeErrorResponse(w, http.StatusInternalServerError, err.Error())
		return
	}

	// Respond with the list of matching files
	response := searchResponse{Files: files}
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(response); err != nil {
		writeErrorResponse(w, http.StatusInternalServerError, "Failed to encode response")
	}
}

func searchFiles(dir string, regex *regexp.Regexp, recursive bool) ([]string, error) {
	var matchingFiles []string

	// Walk through the directory
	err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		// Skip directories unless recursive is true
		if info.IsDir() {
			if !recursive && path != dir {
				return filepath.SkipDir
			}
			return nil
		}

		// Read file content
		content, err := ioutil.ReadFile(path)
		if err != nil {
			return err
		}

		// Check if the file content matches the regex
		if regex.Match(content) {
			relativePath, err := filepath.Rel(dir, path)
			if err != nil {
				return err
			}
			matchingFiles = append(matchingFiles, relativePath)
		}

		return nil
	})

	if err != nil {
		return nil, err
	}

	return matchingFiles, nil
}

func writeErrorResponse(w http.ResponseWriter, statusCode int, message string) {
	w.WriteHeader(statusCode)
	w.Header().Set("Content-Type", "application/json")
	response := errorResponse{Error: message}
	_ = json.NewEncoder(w).Encode(response)
}

package main

import (
	"database/sql"
	"encoding/json"
	"errors"
	"log"
	"net/http"
	"os"

	"github.com/golang-jwt/jwt/v5"
	"github.com/google/uuid"
	_ "github.com/mattn/go-sqlite3"
)

var db *sql.DB
var appSecret string

type User struct {
	Email    string `json:"email"`
	Username string `json:"username"`
	Password string `json:"password"`
}

type LoginRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

type SecretRequest struct {
	Username string `json:"username"`
	Secret   string `json:"secret"`
}

type ErrorResponse struct {
	Message string `json:"message"`
}

type SuccessResponse struct {
	Message string `json:"message"`
}

type TokenResponse struct {
	Token   string `json:"token"`
	Message string `json:"message"`
}

type SecretResponse struct {
	Secret string `json:"secret"`
}

func initDB() {
	var err error
	db, err = sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}

	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS users (
			id TEXT PRIMARY KEY,
			email TEXT UNIQUE NOT NULL,
			username TEXT UNIQUE NOT NULL,
			password TEXT NOT NULL
		);
		CREATE TABLE IF NOT EXISTS secrets (
			id TEXT PRIMARY KEY,
			username TEXT NOT NULL,
			secret TEXT NOT NULL,
			FOREIGN KEY (username) REFERENCES users(username)
		);
	`)
	if err != nil {
		log.Fatalf("Failed to initialize database: %v", err)
	}
}

func registerHandler(w http.ResponseWriter, r *http.Request) {
	var user User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, `{"message":"Invalid request body"}`, http.StatusBadRequest)
		return
	}

	if user.Email == "" || user.Username == "" || user.Password == "" {
		http.Error(w, `{"message":"Missing required fields"}`, http.StatusBadRequest)
		return
	}

	_, err := db.Exec("INSERT INTO users (id, email, username, password) VALUES (?, ?, ?, ?)",
		uuid.New().String(), user.Email, user.Username, user.Password)
	if err != nil {
		http.Error(w, `{"message":"Email or username already in use"}`, http.StatusBadRequest)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(SuccessResponse{Message: "Registration successful"})
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	var loginReq LoginRequest
	if err := json.NewDecoder(r.Body).Decode(&loginReq); err != nil {
		http.Error(w, `{"message":"Invalid request body"}`, http.StatusBadRequest)
		return
	}

	if loginReq.Email == "" || loginReq.Password == "" {
		http.Error(w, `{"message":"Missing required fields"}`, http.StatusBadRequest)
		return
	}

	var username string
	err := db.QueryRow("SELECT username FROM users WHERE email = ? AND password = ?", loginReq.Email, loginReq.Password).Scan(&username)
	if err != nil {
		http.Error(w, `{"message":"Invalid email or password"}`, http.StatusUnauthorized)
		return
	}

	token := jwt.NewWithClaims(jwt.SigningMethodHS256, jwt.MapClaims{
		"username": username,
	})
	tokenString, err := token.SignedString([]byte(appSecret))
	if err != nil {
		http.Error(w, `{"message":"Failed to generate token"}`, http.StatusInternalServerError)
		return
	}

	json.NewEncoder(w).Encode(TokenResponse{Token: tokenString, Message: "Login successful"})
}

func setSecretHandler(w http.ResponseWriter, r *http.Request) {
	var secretReq SecretRequest
	if err := json.NewDecoder(r.Body).Decode(&secretReq); err != nil {
		http.Error(w, `{"message":"Invalid request body"}`, http.StatusBadRequest)
		return
	}

	if secretReq.Username == "" || secretReq.Secret == "" {
		http.Error(w, `{"message":"Missing required fields"}`, http.StatusBadRequest)
		return
	}

	_, err := db.Exec("INSERT INTO secrets (id, username, secret) VALUES (?, ?, ?) ON CONFLICT(username) DO UPDATE SET secret = ?",
