			http.Error(w, `{"message":"Secret not found"}`, http.StatusNotFound)
		} else {
			http.Error(w, `{"message":"Failed to retrieve secret"}`, http.StatusInternalServerError)
		}
		return
	}

	json.NewEncoder(w).Encode(SecretResponse{Secret: secret})
}

