    console.error('Error during GIF creation:', err);
    ctx.status = 500;
    ctx.body = { error: 'Failed to create GIF' };
  } finally {
    // Clean up temporary files
    fs.rmSync(tempDir, { recursive: true, force: true });
    files.forEach((file) => {
      if (fs.existsSync(file.path)) {
        fs.unlinkSync(file.path);
      }
    });
  }
});

