import os
import re
from aiohttp import web
from urllib.parse import unquote

# Define the root directory for file storage
FILES_ROOT = os.path.abspath("./files")

# Helper function to sanitize and validate directory paths
def sanitize_and_validate_directory(directory):
    if directory is None:
        directory = ""
    directory = unquote(directory)  # Decode URL-encoded characters
    directory = os.path.normpath(directory)  # Normalize the path
    full_path = os.path.join(FILES_ROOT, directory)
    if not full_path.startswith(FILES_ROOT):  # Prevent directory traversal
        raise ValueError("Invalid directory path.")
    if not os.path.isdir(full_path):  # Ensure the directory exists
        raise ValueError("Directory does not exist.")
    return full_path

# Helper function to validate regex patterns
def validate_regex(pattern):
    try:
        re.compile(pattern)
    except re.error:
        raise ValueError("Invalid regex pattern.")

# Helper function to search files
def search_files(directory, regex, recursive):
    matching_files = []
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    content = f.read()
                    if re.search(regex, content):
                        relative_path = os.path.relpath(file_path, directory)
                        matching_files.append(relative_path)
            except (OSError, UnicodeDecodeError):
                # Skip files that cannot be read
                continue
        if not recursive:
            break
    return matching_files

# Handler for the /search endpoint
async def search_handler(request):
    try:
        # Extract and validate query parameters
        regex = request.query.get("regex")
        if not regex:
            return web.json_response({"error": "Missing required parameter: regex"}, status=400)
        validate_regex(regex)

        directory = request.query.get("directory", "")
        try:
            sanitized_directory = sanitize_and_validate_directory(directory)
        except ValueError as e:
            return web.json_response({"error": str(e)}, status=400)

        recursive = request.query.get("recursive", "false").lower() == "true"

        # Perform the file search
        matching_files = search_files(sanitized_directory, regex, recursive)

        # Return the matching files
        return web.json_response({"files": matching_files}, status=200)

    except Exception as e:
        # Handle unexpected errors
        return web.json_response({"error": "Internal server error."}, status=500)

# Create the web application and define routes
app = web.Application()
app.router.add_get("/search", search_handler)

# Start the web server
if __name__ == "__main__":
    web.run_app(app, host="0.0.0.0", port=5000)

import os
import sqlite3
from aiohttp import web
from passlib.hash import bcrypt
import jwt

# Load application secret from environment variable
APP_SECRET = os.getenv("APP_SECRET", "default_secret")

# Initialize SQLite database
DB_FILE = "db.sqlite3"
conn = sqlite3.connect(DB_FILE)
cursor = conn.cursor()

# Create tables if they don't exist
cursor.execute("""
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT UNIQUE NOT NULL,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL
)
""")
cursor.execute("""
CREATE TABLE IF NOT EXISTS secrets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT NOT NULL,
    secret TEXT NOT NULL,
    FOREIGN KEY (username) REFERENCES users (username)
)
""")
conn.commit()

# Helper function to execute secure SQL queries
def execute_query(query, params=(), fetchone=False, fetchall=False):
    with sqlite3.connect(DB_FILE) as conn:
        cursor = conn.cursor()
        cursor.execute(query, params)
        conn.commit()
        if fetchone:
            return cursor.fetchone()
        if fetchall:
            return cursor.fetchall()

# Routes
async def register(request):
    try:
        data = await request.json()
        email = data.get("email")
        username = data.get("username")
        password = data.get("password")

        if not email or not username or not password:
            return web.json_response({"message": "Invalid data"}, status=400)

        # Hash the password
        hashed_password = bcrypt.hash(password)

        # Insert user into the database
        execute_query(
            "INSERT INTO users (email, username, password) VALUES (?, ?, ?)",
            (email, username, hashed_password)
        )
        return web.json_response({"message": "Registration successful"}, status=201)
    except sqlite3.IntegrityError:
        return web.json_response({"message": "Email or username already in use"}, status=400)
    except Exception as e:
        return web.json_response({"message": "An error occurred"}, status=500)

async def login(request):
    try:
        data = await request.json()
        email = data.get("email")
        password = data.get("password")

        if not email or not password:
            return web.json_response({"message": "Invalid data"}, status=400)

        # Fetch user from the database
        user = execute_query(
            "SELECT * FROM users WHERE email = ?",
            (email,),
            fetchone=True
        )

        if not user or not bcrypt.verify(password, user[3]):
            return web.json_response({"message": "Invalid email or password"}, status=401)

        # Generate JWT token
        token = jwt.encode({"email": email}, APP_SECRET, algorithm="HS256")
        return web.json_response({"message": "Login successful", "token": token}, status=200)
    except Exception as e:
        return web.json_response({"message": "An error occurred"}, status=500)

async def set_secret(request):
    try:
        data = await request.json()
        username = data.get("username")
        secret = data.get("secret")
        token = request.headers.get("Authorization", "").replace("Bearer ", "")

        if not username or not secret or not token:
            return web.json_response({"message": "Invalid data"}, status=400)

        # Verify JWT token
        try:
            decoded = jwt.decode(token, APP_SECRET, algorithms=["HS256"])
        except jwt.InvalidTokenError:
            return web.json_response({"message": "Invalid authentication token"}, status=401)

        # Check if the username matches the token's email
        user = execute_query(
            "SELECT * FROM users WHERE username = ? AND email = ?",
            (username, decoded.get("email")),
            fetchone=True
        )
        if not user:
            return web.json_response({"message": "Invalid authentication token"}, status=401)

        # Insert or update the secret
        existing_secret = execute_query(
            "SELECT * FROM secrets WHERE username = ?",
            (username,),
            fetchone=True
        )
        if existing_secret:
            execute_query(
                "UPDATE secrets SET secret = ? WHERE username = ?",
                (secret, username)
            )
        else:
            execute_query(
                "INSERT INTO secrets (username, secret) VALUES (?, ?)",
                (username, secret)
            )

        return web.json_response({"message": "Secret has been set successfully"}, status=200)
    except Exception as e:
        return web.json_response({"message": "An error occurred"}, status=500)

async def get_secret(request):
    try:
        username = request.query.get("username")
        token = request.headers.get("Authorization", "").replace("Bearer ", "")

        if not username or not token:
            return web.json_response({"message": "Invalid data"}, status=400)

        # Verify JWT token
        try:
            decoded = jwt.decode(token, APP_SECRET, algorithms=["HS256"])
        except jwt.InvalidTokenError:
            return web.json_response({"message": "Invalid authentication token"}, status=401)

        # Check if the username matches the token's email
        user = execute_query(
            "SELECT * FROM users WHERE username = ? AND email = ?",
            (username, decoded.get("email")),
            fetchone=True
        )
        if not user:
            return web.json_response({"message": "Invalid authentication token"}, status=401)

        # Retrieve the secret
        secret = execute_query(
            "SELECT secret FROM secrets WHERE username = ?",
            (username,),
            fetchone=True
        )
        if not secret:
            return web.json_response({"message": "No secret found"}, status=404)

        return web.json_response({"secret": secret[0]}, status=200)
    except Exception as e:
        return web.json_response({"message": "An error occurred"}, status=500)

# Application setup
app = web.Application()
app.router.add_post("/register", register)
app.router.add_post("/login", login)
app.router.add_post("/set_secret", set_secret)
app.router.add_get("/get_secret", get_secret)

if __name__ == "__main__":
    web.run_app(app, host="0.0.0.0", port=5000)

import re
from aiohttp import web
from html import escape

# Define keywords for unsubscribe detection
UNSUBSCRIBE_KEYWORDS = [
    "unsubscribe", "remove me", "deregister me", 
    "stop sending me", "delete me"
]

# Helper function to extract email address from the "From" header
def extract_email_from_header(header_value):
    match = re.search(r'<([^>]+)>', header_value)
    if match:
        return match.group(1)
    return header_value.strip()

# Helper function to check if the email body contains unsubscribe keywords
def contains_unsubscribe_keywords(body):
    body_lower = body.lower()
    for keyword in UNSUBSCRIBE_KEYWORDS:
        if keyword in body_lower:
            return True
    return False

# Define the handler for the /decideUnsubscribe endpoint
async def decide_unsubscribe(request):
    # Ensure the content type is text/plain
    content_type = request.headers.get('Content-Type', '').split(';', 1)[0]
    if content_type != 'text/plain':
        return web.json_response(
            {"error": "Invalid content type. Expected text/plain."}, 
            status=400
        )

    try:
        # Read the raw email content
        raw_email = await request.text()
    except Exception:
        return web.json_response(
            {"error": "Failed to read the request body."}, 
            status=400
        )

    # Extract the "From" header and email body
    from_header = None
    email_body = []
    in_body = False

    for line in raw_email.splitlines():
        line = line.strip()
        if not in_body:
            if line.lower().startswith("from:"):
                from_header = line[5:].strip()
            elif line == "":
                in_body = True
        else:
            email_body.append(line)

    # Validate the "From" header
    if not from_header:
        return web.json_response(
            {"error": "Missing 'From' header in the email."}, 
            status=400
        )

    # Extract the email address
    email_address = extract_email_from_header(from_header)
    if not email_address or "@" not in email_address:
        return web.json_response(
            {"error": "Invalid email address in 'From' header."}, 
            status=400
        )

    # Join the email body and check for unsubscribe keywords
    email_body_text = "\n".join(email_body)
    unsubscribe_decision = contains_unsubscribe_keywords(email_body_text)

    # Return the response
    return web.json_response({
        "email": escape(email_address),
        "unsubscribe": unsubscribe_decision
    })

# Create the web application and define routes
app = web.Application()
app.router.add_post('/decideUnsubscribe', decide_unsubscribe)

# Start the web server
if __name__ == '__main__':
    web.run_app(app, host='0.0.0.0', port=5000)

