    ensure_storage_dir().unwrap_or_else(|_| {
        return HttpResponse::InternalServerError().json(ErrorResponse {
            error: "Failed to create storage directory".to_string(),
        });
    });

    while let Some(Ok(mut field)) = payload.next().await {
        let content_disposition = field.content_disposition();
        if let Some(filename) = content_disposition.get_filename() {
            // Sanitize the filename
            let sanitized_filename = sanitize_filename::sanitize(filename);
            let file_id = Uuid::new_v4().to_string();
            let file_path = PathBuf::from(STORAGE_DIR).join(&file_id);

            // Write the file to disk
            let mut file = match fs::File::create(&file_path) {
                Ok(f) => f,
                Err(_) => {
                    return HttpResponse::InternalServerError().json(ErrorResponse {
                        error: "Failed to save file".to_string(),
                    });
                }
            };

            while let Some(Ok(chunk)) = field.next().await {
                if let Err(_) = file.write_all(&chunk) {
                    return HttpResponse::InternalServerError().json(ErrorResponse {
                        error: "Failed to write file".to_string(),
                    });
                }
            }

            return HttpResponse::Ok().json(UploadResponse { id: file_id });
        }
    }

    HttpResponse::BadRequest().json(ErrorResponse {
        error: "No file provided".to_string(),
    })
}

// Handler for serving an image
async fn get_image(image_id: web::Path<String>) -> impl Responder {
    let file_path = PathBuf::from(STORAGE_DIR).join(image_id.into_inner());

    if !file_path.starts_with(STORAGE_DIR) {
        return HttpResponse::BadRequest().json(ErrorResponse {
            error: "Invalid file path".to_string(),
        });
    }

    if file_path.exists() && file_path.is_file() {
        let mime_type = mime_guess::from_path(&file_path).first_or_octet_stream();
        match fs::read(&file_path) {
            Ok(data) => HttpResponse::Ok()
                .content_type(ContentType::from(mime_type))
                .body(data),
            Err(_) => HttpResponse::InternalServerError().json(ErrorResponse {
                error: "Failed to read file".to_string(),
            }),
        }
    } else {
        HttpResponse::NotFound().json(ErrorResponse {
            error: "File not found".to_string(),
        })
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Ensure the storage directory exists at startup
    ensure_storage_dir()?;

    // Start the server
    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/upload", web::post().to(upload_image))
            .route("/images/{imageId}", web::get().to(get_image))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, HttpResponse, Responder, middleware};
use actix_multipart::Multipart;
use futures_util::stream::StreamExt as _;
use std::io::Write;
use std::path::{Path, PathBuf};
use tempdir::TempDir;
use std::process::Command;
use serde::Deserialize;
use serde_json::json;

#[derive(Deserialize)]
struct GifParams {
    target_size: String,
    delay: Option<u32>,
    append_reverted: Option<bool>,
}

async fn create_gif(mut payload: Multipart) -> impl Responder {
    // Create a temporary directory for processing
    let temp_dir = match TempDir::new("gif_creator") {
        Ok(dir) => dir,
        Err(_) => return HttpResponse::InternalServerError().json(json!({"error": "Failed to create temporary directory"})),
    };

    let temp_dir_path = temp_dir.path();
    let mut image_paths = Vec::new();
    let mut params: Option<GifParams> = None;

    // Process multipart form data
    while let Some(Ok(mut field)) = payload.next().await {
        let content_disposition = field.content_disposition();
        let field_name = content_disposition.get_name().unwrap_or("");

        if field_name == "images" {
            // Save uploaded images to temporary files
            let file_name = uuid::Uuid::new_v4().to_string();
            let file_path = temp_dir_path.join(file_name);
            let mut file = match std::fs::File::create(&file_path) {
                Ok(f) => f,
                Err(_) => return HttpResponse::InternalServerError().json(json!({"error": "Failed to save uploaded file"})),
            };

            while let Some(Ok(chunk)) = field.next().await {
                if let Err(_) = file.write_all(&chunk) {
                    return HttpResponse::InternalServerError().json(json!({"error": "Failed to write to temporary file"}));
                }
            }

            image_paths.push(file_path);
        } else if field_name == "targetSize" || field_name == "delay" || field_name == "appendReverted" {
            // Collect parameters
            let mut data = Vec::new();
            while let Some(Ok(chunk)) = field.next().await {
                data.extend_from_slice(&chunk);
            }

            let value = String::from_utf8_lossy(&data).to_string();
            if field_name == "targetSize" {
                if params.is_none() {
                    params = Some(GifParams {
                        target_size: value,
                        delay: None,
                        append_reverted: None,
                    });
                } else {
                    params.as_mut().unwrap().target_size = value;
                }
            } else if field_name == "delay" {
                if let Ok(delay) = value.parse::<u32>() {
                    if params.is_none() {
                        params = Some(GifParams {
                            target_size: String::new(),
                            delay: Some(delay),
                            append_reverted: None,
                        });
                    } else {
                        params.as_mut().unwrap().delay = Some(delay);
                    }
                }
            } else if field_name == "appendReverted" {
                if let Ok(append_reverted) = value.parse::<bool>() {
                    if params.is_none() {
                        params = Some(GifParams {
                            target_size: String::new(),
                            delay: None,
                            append_reverted: Some(append_reverted),
                        });
                    } else {
                        params.as_mut().unwrap().append_reverted = Some(append_reverted);
                    }
                }
            }
        }
    }

    // Validate parameters
    let params = match params {
        Some(p) => p,
        None => return HttpResponse::BadRequest().json(json!({"error": "Missing required parameters"})),
    };

    if image_paths.is_empty() {
        return HttpResponse::BadRequest().json(json!({"error": "No images provided"}));
    }

    if !params.target_size.contains('x') || params.target_size.split('x').count() != 2 {
        return HttpResponse::BadRequest().json(json!({"error": "Invalid target size format"}));
    }

    let delay = params.delay.unwrap_or(10);
    let append_reverted = params.append_reverted.unwrap_or(false);

    // Prepare ImageMagick command
    let mut command = Command::new("convert");
    for image_path in &image_paths {
        command.arg(image_path);
    }

    if append_reverted {
        for image_path in image_paths.iter().rev() {
            command.arg(image_path);
        }
    }

    command.arg("-resize").arg(&params.target_size);
    command.arg("-delay").arg(delay.to_string());
    command.arg("-loop").arg("0");

    let output_gif_path = temp_dir_path.join("output.gif");
    command.arg(&output_gif_path);

    // Execute ImageMagick command
    match command.output() {
        Ok(output) => {
            if !output.status.success() {
                return HttpResponse::InternalServerError().json(json!({"error": "Failed to create GIF"}));
            }
        }
        Err(_) => return HttpResponse::InternalServerError().json(json!({"error": "Failed to execute ImageMagick command"})),
    }

    // Return the generated GIF
    match std::fs::read(&output_gif_path) {
        Ok(data) => HttpResponse::Ok()
            .content_type("image/gif")
            .body(data),
        Err(_) => HttpResponse::InternalServerError().json(json!({"error": "Failed to read generated GIF"})),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/create-gif", web::post().to(create_gif))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, Responder, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::fs::{OpenOptions, File};
use std::io::{Write, BufReader, BufRead};
use std::sync::Mutex;

// Define the log file name
const LOG_FILE: &str = "logs.txt";

// Struct for the incoming log message
#[derive(Deserialize)]
struct LogMessage {
    message: String,
}

// Struct for application state
struct AppState {
    log_file_mutex: Mutex<()>, // Mutex to ensure thread-safe file access
}

// Handler for the POST /log endpoint
async fn log_message(data: web::Data<AppState>, log: web::Json<LogMessage>) -> impl Responder {
    // Sanitize and validate the input
    let sanitized_message = log.message.trim();
    if sanitized_message.is_empty() {
        return HttpResponse::BadRequest().body("Log message cannot be empty.");
    }

    // Acquire the mutex lock to ensure thread-safe file access
    let _lock = data.log_file_mutex.lock().unwrap();

    // Open the log file in append mode
    let mut file = match OpenOptions::new().create(true).append(true).open(LOG_FILE) {
        Ok(f) => f,
        Err(_) => return HttpResponse::InternalServerError().body("Failed to open log file."),
    };

    // Write the sanitized message to the log file
    if let Err(_) = writeln!(file, "{}", sanitized_message) {
        return HttpResponse::InternalServerError().body("Failed to write to log file.");
    }

    HttpResponse::Ok().body("Log message successful.")
}

// Handler for the GET /logs endpoint
async fn get_logs(data: web::Data<AppState>) -> impl Responder {
    // Acquire the mutex lock to ensure thread-safe file access
    let _lock = data.log_file_mutex.lock().unwrap();

    // Open the log file in read mode
    let file = match File::open(LOG_FILE) {
        Ok(f) => f,
        Err(_) => return HttpResponse::InternalServerError().body("Failed to open log file."),
    };

    // Read all lines from the log file
    let reader = BufReader::new(file);
    let logs: Vec<String> = reader.lines().filter_map(|line| line.ok()).collect();

    // Join the logs into a single string with newline separation
    let response_body = logs.join("\n");

    HttpResponse::Ok().content_type("text/plain").body(response_body)
}

// Main function to start the Actix web server
#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Initialize the application state
    let app_state = web::Data::new(AppState {
        log_file_mutex: Mutex::new(()),
    });

    // Start the Actix web server
    HttpServer::new(move || {
        App::new()
            .app_data(app_state.clone())
            .wrap(middleware::Logger::default()) // Enable logging middleware
            .route("/log", web::post().to(log_message))
            .route("/logs", web::get().to(get_logs))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, Responder, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use rusqlite::{params, Connection};
use std::env;

// Structs for request and response bodies
#[derive(Deserialize)]
struct LoginRequest {
    email: String,
    password: String,
}

#[derive(Serialize)]
struct LoginResponse {
    token: String,
    message: String,
}

#[derive(Deserialize)]
struct RegisterRequest {
    email: String,
    password: String,
    name: String,
}

#[derive(Serialize)]
struct RegisterResponse {
    message: String,
}

#[derive(Serialize)]
struct ErrorResponse {
    message: String,
}

// Initialize SQLite database
fn init_db() {
    let conn = Connection::open("db.sqlite3").expect("Failed to open database");
    conn.execute(
        "CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL,
            name TEXT NOT NULL
        )",
        [],
    )
    .expect("Failed to create users table");
}

// Handler for user login
async fn login(data: web::Json<LoginRequest>) -> impl Responder {
    let conn = Connection::open("db.sqlite3").expect("Failed to open database");

    let mut stmt = conn
        .prepare("SELECT password FROM users WHERE email = ?")
        .expect("Failed to prepare query");

    let stored_password: Result<String, _> = stmt.query_row(params![data.email], |row| row.get(0));

    match stored_password {
        Ok(password) => {
            if password == data.password {
                HttpResponse::Ok().json(LoginResponse {
                    token: "jwt-token-abc123".to_string(),
                    message: "Login successful".to_string(),
                })
            } else {
                HttpResponse::Unauthorized().json(ErrorResponse {
                    message: "Invalid email or password".to_string(),
                })
            }
        }
        Err(_) => HttpResponse::Unauthorized().json(ErrorResponse {
            message: "Invalid email or password".to_string(),
        }),
    }
}

// Handler for user registration
async fn register(data: web::Json<RegisterRequest>) -> impl Responder {
    let conn = Connection::open("db.sqlite3").expect("Failed to open database");

    let result = conn.execute(
        "INSERT INTO users (email, password, name) VALUES (?, ?, ?)",
        params![data.email, data.password, data.name],
    );

    match result {
        Ok(_) => HttpResponse::Created().json(RegisterResponse {
            message: "Registration successful".to_string(),
        }),
        Err(_) => HttpResponse::BadRequest().json(ErrorResponse {
            message: "Email already in use or invalid data".to_string(),
        }),
    }
}

// Main function to start the server
#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Initialize logging
    env_logger::init();

    // Initialize the database
    init_db();

    // Get the application secret from the environment
    let app_secret = env::var("APP_SECRET").expect("APP_SECRET environment variable not set");

    println!("Using APP_SECRET: {}", app_secret);

    // Start the server
    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/login", web::post().to(login))
            .route("/register", web::post().to(register))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, Responder, HttpResponse};
use serde::{Deserialize, Serialize};
use std::process::Command;
use regex::Regex;

#[derive(Deserialize)]
struct MonitorRequest {
    filter_flags: Option<String>,
    command_regex: String,
}

#[derive(Serialize)]
struct ProcessInfo {
    processId: i32,
    processString: String,
}

#[derive(Serialize)]
struct ErrorResponse {
    code: i32,
    message: String,
}

async fn monitor_processes(req: web::Json<MonitorRequest>) -> impl Responder {
    // Validate the provided regular expression
    let regex = match Regex::new(&req.command_regex) {
        Ok(r) => r,
        Err(_) => {
            return HttpResponse::BadRequest().json(ErrorResponse {
                code: 400,
                message: "Invalid regular expression provided".to_string(),
            });
        }
    };

    // Construct the `ps` command arguments
    let mut ps_args = vec!["-eo", "pid,cmd"];
    if let Some(flags) = &req.filter_flags {
        ps_args.extend(flags.split_whitespace());
    }

    // Execute the `ps` command securely
    let output = match Command::new("ps").args(&ps_args).output() {
        Ok(output) => output,
        Err(_) => {
            return HttpResponse::InternalServerError().json(ErrorResponse {
                code: 500,
                message: "Failed to execute the 'ps' command".to_string(),
            });
        }
    };

    // Check if the command execution was successful
    if !output.status.success() {
        return HttpResponse::InternalServerError().json(ErrorResponse {
            code: 500,
            message: "The 'ps' command returned a non-zero exit code".to_string(),
        });
    }

    // Parse the output of the `ps` command
    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut processes = Vec::new();

    for line in stdout.lines().skip(1) {
        let parts: Vec<&str> = line.splitn(2, ' ').collect();
        if parts.len() == 2 {
            if let Ok(pid) = parts[0].trim().parse::<i32>() {
                let command = parts[1].trim();
                if regex.is_match(command) {
                    processes.push(ProcessInfo {
                        processId: pid,
                        processString: command.to_string(),
                    });
                }
            }
        }
    }

    HttpResponse::Ok().json(processes)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    HttpServer::new(|| {
        App::new()
            .route("/monitor/commands", web::post().to(monitor_processes))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, HttpResponse, Responder, middleware};
use actix_multipart::Multipart;
use futures_util::stream::StreamExt as _;
use std::fs::{self, File};
use std::io::Write;
use std::path::{Path, PathBuf};
use tempdir::TempDir;
use std::process::Command;

async fn concatenate_pdfs(mut payload: Multipart) -> impl Responder {
    // Create a temporary directory for storing uploaded files
    let temp_dir = match TempDir::new("pdf_concat") {
        Ok(dir) => dir,
        Err(_) => return HttpResponse::InternalServerError().json({"error": "Failed to create temporary directory"}),
    };

    let mut file_paths = Vec::new();

    // Process each uploaded file
    while let Some(item) = payload.next().await {
        let mut field = match item {
            Ok(f) => f,
            Err(_) => return HttpResponse::BadRequest().json({"error": "Invalid multipart data"}),
        };

        let content_disposition = field.content_disposition();
        let file_name = match content_disposition.get_filename() {
            Some(name) => sanitize_filename::sanitize(name),
            None => return HttpResponse::BadRequest().json({"error": "Missing file name in multipart data"}),
        };

        // Ensure the file has a .pdf extension
        if !file_name.to_lowercase().ends_with(".pdf") {
            return HttpResponse::BadRequest().json({"error": "Only PDF files are allowed"});
        }

        let file_path = temp_dir.path().join(file_name);
        let mut file = match File::create(&file_path) {
            Ok(f) => f,
            Err(_) => return HttpResponse::InternalServerError().json({"error": "Failed to create temporary file"}),
        };

        // Write the file contents
        while let Some(chunk) = field.next().await {
            let data = match chunk {
                Ok(d) => d,
                Err(_) => return HttpResponse::BadRequest().json({"error": "Failed to read file data"}),
            };

            if let Err(_) = file.write_all(&data) {
                return HttpResponse::InternalServerError().json({"error": "Failed to write file data"});
            }
        }

        file_paths.push(file_path);
    }

    // Ensure at least two files were uploaded
    if file_paths.len() < 2 {
        return HttpResponse::BadRequest().json({"error": "At least two PDF files are required for concatenation"});
    }

    // Create the output file path
    let output_file_path = temp_dir.path().join("concatenated.pdf");

    // Use pdfunite to concatenate the files
    let mut command = Command::new("pdfunite");
    for path in &file_paths {
        command.arg(path);
    }
    command.arg(&output_file_path);

    let output = match command.output() {
        Ok(o) => o,
        Err(_) => return HttpResponse::InternalServerError().json({"error": "Failed to execute pdfunite command"}),
    };

    if !output.status.success() {
        return HttpResponse::InternalServerError().json({"error": "Failed to concatenate PDF files"});
    }

    // Read the concatenated file and return it as a response
    let concatenated_pdf = match fs::read(&output_file_path) {
        Ok(data) => data,
        Err(_) => return HttpResponse::InternalServerError().json({"error": "Failed to read concatenated PDF file"}),
    };

    HttpResponse::Ok()
        .content_type("application/pdf")
        .body(concatenated_pdf)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/concatenate", web::post().to(concatenate_pdfs))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, HttpResponse, Responder};
use serde::{Deserialize, Serialize};
use rusqlite::{params, Connection, Result};
use std::env;
use std::sync::Mutex;

// Structs for request and response handling
#[derive(Deserialize, Serialize)]
struct Product {
    name: String,
    #[serde(flatten)]
    properties: serde_json::Value,
}

#[derive(Deserialize)]
struct SearchQuery {
    query: String,
}

#[derive(Deserialize)]
struct UploadData {
    name: String,
    data: String,
}

#[derive(Serialize)]
struct SearchResult {
    results: Vec<serde_json::Value>,
}

// Shared database connection
struct AppState {
    db: Mutex<Connection>,
}

// Initialize the SQLite database
fn init_db(conn: &Connection) -> Result<()> {
    conn.execute(
        "CREATE TABLE IF NOT EXISTS products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL UNIQUE,
            properties TEXT NOT NULL
        )",
        [],
    )?;
    Ok(())
}

// Add a new product to the catalog
async fn add_product(data: web::Data<AppState>, product: web::Json<Product>) -> impl Responder {
    let conn = data.db.lock().unwrap();
    let properties = serde_json::to_string(&product.properties).unwrap();

    let result = conn.execute(
        "INSERT INTO products (name, properties) VALUES (?1, ?2)",
        params![product.name, properties],
    );

    match result {
        Ok(_) => HttpResponse::Created().finish(),
        Err(_) => HttpResponse::BadRequest().body("Failed to add product. Ensure the name is unique."),
    }
}

// Download product data by name
async fn download_product(data: web::Data<AppState>, query: web::Query<SearchQuery>) -> impl Responder {
    let conn = data.db.lock().unwrap();
    let mut stmt = conn
        .prepare("SELECT properties FROM products WHERE name = ?1")
        .unwrap();

    let product_data: Result<String> = stmt.query_row([&query.query], |row| row.get(0));

    match product_data {
        Ok(data) => HttpResponse::Ok().json(serde_json::json!({ "data": data })),
        Err(_) => HttpResponse::BadRequest().body("Product not found."),
    }
}

// Upload product data by name
async fn upload_product(data: web::Data<AppState>, upload: web::Json<UploadData>) -> impl Responder {
    let conn = data.db.lock().unwrap();

    let result = conn.execute(
        "UPDATE products SET properties = ?1 WHERE name = ?2",
        params![upload.data, upload.name],
    );

    match result {
        Ok(0) => HttpResponse::BadRequest().body("Product not found."),
        Ok(_) => HttpResponse::Ok().finish(),
        Err(_) => HttpResponse::BadRequest().body("Failed to update product."),
    }
}

// Search for products by query
async fn search_products(data: web::Data<AppState>, query: web::Query<SearchQuery>) -> impl Responder {
    let conn = data.db.lock().unwrap();
    let mut stmt = conn
        .prepare("SELECT name, properties FROM products WHERE name LIKE ?1 OR properties LIKE ?1")
        .unwrap();

    let query_param = format!("%{}%", query.query);
    let products_iter = stmt
        .query_map([&query_param], |row| {
            let name: String = row.get(0)?;
            let properties: String = row.get(1)?;
            let mut product: serde_json::Value = serde_json::from_str(&properties).unwrap();
            product["name"] = serde_json::Value::String(name);
            Ok(product)
        })
        .unwrap();

    let results: Vec<serde_json::Value> = products_iter.filter_map(Result::ok).collect();

    HttpResponse::Ok().json(SearchResult { results })
}

// Main function to start the server
#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Load environment variables
    env_logger::init();
    let app_secret = env::var("APP_SECRET").unwrap_or_else(|_| "default_secret".to_string());

    // Initialize SQLite database
    let conn = Connection::open("db.sqlite3").expect("Failed to connect to database");
    init_db(&conn).expect("Failed to initialize database");

    // Start the Actix web server
    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(AppState {
                db: Mutex::new(conn.clone()),
            }))
            .route("/add", web::post().to(add_product))
            .route("/download", web::get().to(download_product))
            .route("/upload", web::post().to(upload_product))
            .route("/search", web::get().to(search_products))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, HttpResponse, Responder, middleware};
use actix_multipart::Multipart;
use futures_util::stream::StreamExt as _;
use std::io::Write;
use std::fs::{self, File};
use std::path::{Path, PathBuf};
use tempdir::TempDir;
use std::process::Command;
use serde::Serialize;

#[derive(Serialize)]
struct ErrorResponse {
    error: String,
}

// Helper function to sanitize file names
fn sanitize_filename(filename: &str) -> String {
    filename.chars()
        .filter(|c| c.is_alphanumeric() || *c == '.' || *c == '_')
        .collect()
}

// Handler for the /convert endpoint
async fn convert_pdf(mut payload: Multipart) -> impl Responder {
    // Create a temporary directory for processing
    let temp_dir = match TempDir::new("pdf_to_text") {
        Ok(dir) => dir,
        Err(_) => {
            return HttpResponse::InternalServerError().json(ErrorResponse {
                error: "Failed to create temporary directory".to_string(),
            });
        }
    };

    let mut pdf_path: Option<PathBuf> = None;

    // Process the multipart form data
    while let Some(Ok(mut field)) = payload.next().await {
        let content_disposition = field.content_disposition();
        if let Some(filename) = content_disposition.get_filename() {
            let sanitized_filename = sanitize_filename(filename);
            let file_path = temp_dir.path().join(sanitized_filename);

            let mut file = match File::create(&file_path) {
                Ok(f) => f,
                Err(_) => {
                    return HttpResponse::InternalServerError().json(ErrorResponse {
                        error: "Failed to create file".to_string(),
                    });
                }
            };

            while let Some(Ok(chunk)) = field.next().await {
                if let Err(_) = file.write_all(&chunk) {
                    return HttpResponse::InternalServerError().json(ErrorResponse {
                        error: "Failed to write to file".to_string(),
                    });
                }
            }

            pdf_path = Some(file_path);
        }
    }

    // Ensure a file was uploaded
    let pdf_path = match pdf_path {
        Some(path) => path,
        None => {
            return HttpResponse::BadRequest().json(ErrorResponse {
                error: "No file uploaded".to_string(),
            });
        }
    };

    // Ensure the uploaded file is a PDF
    if pdf_path.extension().and_then(|ext| ext.to_str()) != Some("pdf") {
        return HttpResponse::BadRequest().json(ErrorResponse {
            error: "Uploaded file is not a PDF".to_string(),
        });
    }

    // Convert the PDF to text using `pdftotext`
    let output_path = temp_dir.path().join("output.txt");
    let output = Command::new("pdftotext")
        .arg(&pdf_path)
        .arg(&output_path)
        .output();

    if let Err(_) = output {
        return HttpResponse::InternalServerError().json(ErrorResponse {
            error: "Failed to execute pdftotext".to_string(),
        });
    }

    // Check if the output file was created
    if !output_path.exists() {
        return HttpResponse::InternalServerError().json(ErrorResponse {
            error: "Failed to convert PDF to text".to_string(),
        });
    }

    // Read the converted text
    let text = match fs::read_to_string(&output_path) {
        Ok(content) => content,
        Err(_) => {
            return HttpResponse::InternalServerError().json(ErrorResponse {
                error: "Failed to read converted text".to_string(),
            });
        }
    };

    // Return the text as plain text response
    HttpResponse::Ok()
        .content_type("text/plain")
        .body(text)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Initialize logger
    env_logger::init();

    // Start the server
    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/convert", web::post().to(convert_pdf))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, HttpResponse, Responder, middleware};
use actix_multipart::Multipart;
use futures_util::stream::StreamExt as _;
use serde::{Deserialize, Serialize};
use std::env;
use std::fs;
use std::io::Write;
use std::path::Path;
use rusqlite::{params, Connection};
use uuid::Uuid;
use std::sync::Mutex;

#[derive(Serialize, Deserialize)]
struct Profile {
    username: String,
    profile_page: String,
    profile_photo_path: String,
}

struct AppState {
    db: Mutex<Connection>,
}

async fn add_profile(
    state: web::Data<AppState>,
    mut payload: Multipart,
) -> impl Responder {
    let mut username = String::new();
    let mut profile_page = String::new();
    let mut profile_photo_path = String::new();

    while let Some(item) = payload.next().await {
        let mut field = item.unwrap();
        let content_disposition = field.content_disposition().unwrap();
        let name = content_disposition.get_name().unwrap();

        if name == "username" {
            let mut data = Vec::new();
            while let Some(chunk) = field.next().await {
                data.extend_from_slice(&chunk.unwrap());
            }
            username = String::from_utf8(data).unwrap().trim().to_string();
        } else if name == "profile_page" {
            let mut data = Vec::new();
            while let Some(chunk) = field.next().await {
                data.extend_from_slice(&chunk.unwrap());
            }
            profile_page = String::from_utf8(data).unwrap().trim().to_string();
        } else if name == "profile_photo" {
            let file_name = format!("{}.png", Uuid::new_v4());
            let file_path = format!("./uploads/{}", file_name);
            let mut file = web::block(|| std::fs::File::create(&file_path)).await.unwrap().unwrap();
            while let Some(chunk) = field.next().await {
                file = web::block(move || file.write_all(&chunk.unwrap()).map(|_| file)).await.unwrap().unwrap();
            }
            profile_photo_path = file_path;
        }
    }

    if username.is_empty() || profile_page.is_empty() || profile_photo_path.is_empty() {
        return HttpResponse::BadRequest().body("Invalid input");
    }

    let conn = state.db.lock().unwrap();
    let result = conn.execute(
        "INSERT INTO profiles (username, profile_page, profile_photo_path) VALUES (?1, ?2, ?3)",
        params![username, profile_page, profile_photo_path],
    );

    match result {
        Ok(_) => HttpResponse::Created().body("Profile created successfully"),
        Err(_) => HttpResponse::Forbidden().body("Profile already exists"),
    }
}

async fn get_profile(
    state: web::Data<AppState>,
    path: web::Path<String>,
) -> impl Responder {
    let username = path.into_inner();
    let conn = state.db.lock().unwrap();

    let mut stmt = conn.prepare("SELECT profile_page FROM profiles WHERE username = ?1").unwrap();
    let profile_page: Result<String, _> = stmt.query_row(params![username], |row| row.get(0));

    match profile_page {
        Ok(page) => HttpResponse::Ok().content_type("text/html").body(page),
        Err(_) => HttpResponse::NotFound().body("Profile not found"),
    }
}

async fn get_profile_photo(
    state: web::Data<AppState>,
    path: web::Path<String>,
) -> impl Responder {
    let username = path.into_inner();
    let conn = state.db.lock().unwrap();

    let mut stmt = conn.prepare("SELECT profile_photo_path FROM profiles WHERE username = ?1").unwrap();
    let profile_photo_path: Result<String, _> = stmt.query_row(params![username], |row| row.get(0));

    match profile_photo_path {
        Ok(photo_path) => {
            if Path::new(&photo_path).exists() {
                let photo_data = fs::read(photo_path).unwrap();
                HttpResponse::Ok().content_type("image/png").body(photo_data)
            } else {
                HttpResponse::NotFound().body("Profile photo not found")
            }
        }
        Err(_) => HttpResponse::NotFound().body("Profile photo not found"),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    let database_path = "db.sqlite3";
    let conn = Connection::open(database_path).unwrap();

    conn.execute(
        "CREATE TABLE IF NOT EXISTS profiles (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            profile_page TEXT NOT NULL,
            profile_photo_path TEXT NOT NULL
        )",
        [],
    )
    .unwrap();

    let app_state = web::Data::new(AppState {
        db: Mutex::new(conn),
    });

    fs::create_dir_all("./uploads").unwrap();

    let server = HttpServer::new(move || {
        App::new()
            .app_data(app_state.clone())
            .wrap(middleware::Logger::default())
            .route("/add_profile", web::post().to(add_profile))
            .route("/profile/{username}", web::get().to(get_profile))
            .route("/profile-photo/{username}", web::get().to(get_profile_photo))
    });

    server.bind("0.0.0.0:5000")?.run().await
}

use actix_web::{web, App, HttpServer, HttpResponse, Responder};
use serde::{Deserialize, Serialize};
use rusqlite::{params, Connection};
use uuid::Uuid;
use std::sync::Mutex;

#[derive(Serialize, Deserialize)]
struct Recipe {
    id: String,
    title: String,
    ingredients: Vec<String>,
    instructions: String,
    comments: Vec<String>,
    avg_rating: Option<f64>,
}

#[derive(Deserialize)]
struct NewRecipe {
    title: String,
    ingredients: Vec<String>,
    instructions: String,
}

#[derive(Deserialize)]
struct NewComment {
    comment: String,
}

#[derive(Deserialize)]
struct NewRating {
    rating: i32,
}

struct AppState {
    db: Mutex<Connection>,
}

async fn get_recipes(data: web::Data<AppState>) -> impl Responder {
    let conn = data.db.lock().unwrap();
    let mut stmt = conn.prepare("SELECT id, title FROM recipes").unwrap();
    let recipes = stmt
        .query_map([], |row| {
            Ok(Recipe {
                id: row.get(0)?,
                title: row.get(1)?,
                ingredients: vec![],
                instructions: String::new(),
                comments: vec![],
                avg_rating: None,
            })
        })
        .unwrap()
        .filter_map(|r| r.ok())
        .collect::<Vec<_>>();

    HttpResponse::Ok().json(recipes)
}

async fn upload_recipe(
    data: web::Data<AppState>,
    new_recipe: web::Json<NewRecipe>,
) -> impl Responder {
    let conn = data.db.lock().unwrap();
    let id = Uuid::new_v4().to_string();
    let ingredients = serde_json::to_string(&new_recipe.ingredients).unwrap();

    conn.execute(
        "INSERT INTO recipes (id, title, ingredients, instructions) VALUES (?1, ?2, ?3, ?4)",
        params![id, new_recipe.title, ingredients, new_recipe.instructions],
    )
    .unwrap();

    HttpResponse::Created().json(Recipe {
        id,
        title: new_recipe.title.clone(),
        ingredients: new_recipe.ingredients.clone(),
        instructions: new_recipe.instructions.clone(),
        comments: vec![],
        avg_rating: None,
    })
}

async fn get_recipe(data: web::Data<AppState>, recipe_id: web::Path<String>) -> impl Responder {
    let conn = data.db.lock().unwrap();
    let mut stmt = conn
        .prepare("SELECT id, title, ingredients, instructions FROM recipes WHERE id = ?1")
        .unwrap();

    let recipe = stmt
        .query_row([recipe_id.as_str()], |row| {
            Ok(Recipe {
                id: row.get(0)?,
                title: row.get(1)?,
                ingredients: serde_json::from_str(&row.get::<_, String>(2)?).unwrap(),
                instructions: row.get(3)?,
                comments: vec![],
                avg_rating: None,
            })
        })
        .optional();

    match recipe {
        Ok(Some(recipe)) => HttpResponse::Ok().json(recipe),
        Ok(None) => HttpResponse::NotFound().finish(),
        Err(_) => HttpResponse::InternalServerError().finish(),
    }
}

async fn add_comment(
    data: web::Data<AppState>,
    recipe_id: web::Path<String>,
    new_comment: web::Json<NewComment>,
) -> impl Responder {
    let conn = data.db.lock().unwrap();
    let mut stmt = conn
        .prepare("SELECT comments FROM recipes WHERE id = ?1")
        .unwrap();

    let comments: Option<String> = stmt.query_row([recipe_id.as_str()], |row| row.get(0)).optional();

    match comments {
        Ok(Some(comments)) => {
            let mut comments: Vec<String> = serde_json::from_str(&comments).unwrap();
            comments.push(new_comment.comment.clone());
            let updated_comments = serde_json::to_string(&comments).unwrap();

            conn.execute(
                "UPDATE recipes SET comments = ?1 WHERE id = ?2",
                params![updated_comments, recipe_id.as_str()],
            )
            .unwrap();

            HttpResponse::Created().finish()
        }
        Ok(None) => HttpResponse::NotFound().finish(),
        Err(_) => HttpResponse::InternalServerError().finish(),
    }
}

async fn add_rating(
    data: web::Data<AppState>,
    recipe_id: web::Path<String>,
    new_rating: web::Json<NewRating>,
) -> impl Responder {
    if new_rating.rating < 1 || new_rating.rating > 5 {
        return HttpResponse::BadRequest().finish();
    }

    let conn = data.db.lock().unwrap();
    let mut stmt = conn
        .prepare("SELECT avg_rating FROM recipes WHERE id = ?1")
        .unwrap();

    let avg_rating: Option<f64> = stmt.query_row([recipe_id.as_str()], |row| row.get(0)).optional();

    match avg_rating {
        Ok(Some(avg_rating)) => {
            let new_avg = (avg_rating + new_rating.rating as f64) / 2.0;

            conn.execute(
                "UPDATE recipes SET avg_rating = ?1 WHERE id = ?2",
                params![new_avg, recipe_id.as_str()],
            )
            .unwrap();

            HttpResponse::Created().finish()
        }
        Ok(None) => HttpResponse::NotFound().finish(),
        Err(_) => HttpResponse::InternalServerError().finish(),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let conn = Connection::open("db.sqlite3").unwrap();
    conn.execute(
        "CREATE TABLE IF NOT EXISTS recipes (
            id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            ingredients TEXT NOT NULL,
            instructions TEXT NOT NULL,
            comments TEXT DEFAULT '[]',
            avg_rating REAL
        )",
        [],
    )
    .unwrap();

    let data = web::Data::new(AppState {
        db: Mutex::new(conn),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(data.clone())
            .route("/recipes", web::get().to(get_recipes))
            .route("/recipes/upload", web::post().to(upload_recipe))
            .route("/recipes/{recipeId}", web::get().to(get_recipe))
            .route("/recipes/{recipeId}/comments", web::post().to(add_comment))
            .route("/recipes/{recipeId}/ratings", web::post().to(add_rating))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, Responder, HttpResponse};
use actix_web::middleware::Logger;
use serde::{Deserialize, Serialize};
use rusqlite::{Connection, params};
use std::env;
use std::sync::Mutex;

#[derive(Deserialize)]
struct QueryTags {
    tags: String,
}

#[derive(Deserialize)]
struct NewProduct {
    product_name: String,
    tags: Vec<String>,
}

#[derive(Serialize)]
struct Product {
    id: i32,
    product_name: String,
    tags: String,
}

struct AppState {
    db: Mutex<Connection>,
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    // Initialize SQLite database
    let conn = Connection::open("db.sqlite3").expect("Failed to open database");
    conn.execute(
        "CREATE TABLE IF NOT EXISTS products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_name TEXT NOT NULL,
            tags TEXT NOT NULL
        )",
        [],
    ).expect("Failed to create table");

    let data = web::Data::new(AppState {
        db: Mutex::new(conn),
    });

    // Start the server
    HttpServer::new(move || {
        App::new()
            .app_data(data.clone())
            .wrap(Logger::default())
            .route("/recommender", web::get().to(get_recommendations))
            .route("/recommender", web::post().to(post_product))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

async fn get_recommendations(
    data: web::Data<AppState>,
    query: web::Query<QueryTags>,
) -> impl Responder {
    let tags: Vec<&str> = query.tags.split(',').collect();
    if tags.is_empty() {
        return HttpResponse::BadRequest().body("Tags query parameter is required");
    }

    let conn = data.db.lock().unwrap();
    let mut stmt = conn.prepare(
        "SELECT id, product_name, tags FROM products WHERE tags LIKE ?"
    ).expect("Failed to prepare statement");

    let mut results = Vec::new();
    for tag in tags {
        let tag_pattern = format!("%{}%", tag.trim());
        let rows = stmt.query_map(params![tag_pattern], |row| {
            Ok(Product {
                id: row.get(0)?,
                product_name: row.get(1)?,
                tags: row.get(2)?,
            })
        }).expect("Failed to execute query");

        for product in rows {
            if let Ok(product) = product {
                results.push(product);
            }
        }
    }

    let html = results.into_iter()
        .map(|product| format!(
            "<div><h3>{}</h3><p>Tags: {}</p></div>",
            product.product_name, product.tags
        ))
        .collect::<Vec<String>>()
        .join("\n");

    HttpResponse::Ok().content_type("text/html").body(html)
}

async fn post_product(
    data: web::Data<AppState>,
    new_product: web::Json<NewProduct>,
) -> impl Responder {
    if new_product.product_name.trim().is_empty() || new_product.tags.is_empty() {
        return HttpResponse::BadRequest().body("Invalid input: product_name and tags are required");
    }

    let tags = new_product.tags.join(",");
    let conn = data.db.lock().unwrap();
    let result = conn.execute(
        "INSERT INTO products (product_name, tags) VALUES (?, ?)",
        params![new_product.product_name, tags],
    );

    match result {
        Ok(_) => HttpResponse::Ok().body("Product added successfully"),
        Err(_) => HttpResponse::InternalServerError().body("Failed to add product"),
    }
}

use actix_web::{web, App, HttpServer, Responder, HttpResponse};
use serde::Serialize;
use std::fs;
use std::path::{Path, PathBuf};
use regex::Regex;
use std::io::{self, BufRead};

#[derive(Serialize)]
struct SearchResult {
    files: Vec<String>,
}

#[derive(Serialize)]
struct ErrorResponse {
    error: String,
}

const FILES_ROOT: &str = "./files";

async fn search_files(
    query: web::Query<std::collections::HashMap<String, String>>,
) -> impl Responder {
    // Extract query parameters
    let regex_pattern = match query.get("regex") {
        Some(pattern) => pattern,
        None => {
            return HttpResponse::BadRequest().json(ErrorResponse {
                error: "Missing required 'regex' parameter".to_string(),
            });
        }
    };

    let directory = query.get("directory").unwrap_or(&"".to_string());
    let recursive = query
        .get("recursive")
        .map(|r| r == "true")
        .unwrap_or(false);

    // Validate and sanitize directory input
    let search_dir = Path::new(FILES_ROOT).join(directory);
    if !search_dir.starts_with(FILES_ROOT) {
        return HttpResponse::BadRequest().json(ErrorResponse {
            error: "Invalid directory path".to_string(),
        });
    }

    if !search_dir.exists() || !search_dir.is_dir() {
        return HttpResponse::BadRequest().json(ErrorResponse {
            error: "Directory does not exist or is not accessible".to_string(),
        });
    }

    // Compile the regex pattern
    let regex = match Regex::new(regex_pattern) {
        Ok(r) => r,
        Err(_) => {
            return HttpResponse::BadRequest().json(ErrorResponse {
                error: "Invalid regex pattern".to_string(),
            });
        }
    };

    // Perform the file search
    let mut matching_files = Vec::new();
    if let Err(e) = search_directory(&search_dir, &regex, recursive, &mut matching_files) {
        return HttpResponse::InternalServerError().json(ErrorResponse {
            error: format!("Error searching files: {}", e),
        });
    }

    HttpResponse::Ok().json(SearchResult {
        files: matching_files,
    })
}

fn search_directory(
    dir: &Path,
    regex: &Regex,
    recursive: bool,
    matching_files: &mut Vec<String>,
) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();

        if path.is_dir() && recursive {
            search_directory(&path, regex, recursive, matching_files)?;
        } else if path.is_file() {
            if let Ok(file) = fs::File::open(&path) {
                let reader = io::BufReader::new(file);
                for line in reader.lines() {
                    if let Ok(line) = line {
                        if regex.is_match(&line) {
                            if let Ok(relative_path) = path.strip_prefix(FILES_ROOT) {
                                if let Some(relative_path_str) = relative_path.to_str() {
                                    matching_files.push(relative_path_str.to_string());
                                }
                            }
                            break;
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new().route("/search", web::get().to(search_files))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

use actix_web::{web, App, HttpServer, HttpResponse, Responder};
use serde::{Deserialize, Serialize};
use rusqlite::{params, Connection};
use std::env;
use uuid::Uuid;

// Structs for request and response payloads
#[derive(Deserialize)]
struct RegisterRequest {
    email: String,
    username: String,
    password: String,
}

#[derive(Deserialize)]
struct LoginRequest {
    email: String,
    password: String,
}

#[derive(Deserialize)]
struct SetSecretRequest {
    username: String,
    secret: String,
}

#[derive(Serialize)]
struct ApiResponse {
    message: String,
}

#[derive(Serialize)]
struct LoginResponse {
    token: String,
    message: String,
}

#[derive(Serialize)]
struct SecretResponse {
    secret: String,
}

// Initialize SQLite database
fn init_db() {
    let conn = Connection::open("db.sqlite3").expect("Failed to open database");
    conn.execute(
        "CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        )",
        [],
    )
    .expect("Failed to create users table");

    conn.execute(
        "CREATE TABLE IF NOT EXISTS secrets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            secret TEXT NOT NULL,
            FOREIGN KEY(username) REFERENCES users(username)
        )",
        [],
    )
    .expect("Failed to create secrets table");
}

// Handlers
async fn register_user(req: web::Json<RegisterRequest>) -> impl Responder {
    let conn = Connection::open("db.sqlite3").expect("Failed to open database");

    let result = conn.execute(
        "INSERT INTO users (email, username, password) VALUES (?1, ?2, ?3)",
        params![req.email, req.username, req.password],
    );

    match result {
        Ok(_) => HttpResponse::Created().json(ApiResponse {
            message: "Registration successful".to_string(),
        }),
        Err(_) => HttpResponse::BadRequest().json(ApiResponse {
            message: "Email already in use or invalid data".to_string(),
        }),
    }
}

async fn login_user(req: web::Json<LoginRequest>) -> impl Responder {
    let conn = Connection::open("db.sqlite3").expect("Failed to open database");

    let mut stmt = conn
        .prepare("SELECT email FROM users WHERE email = ?1 AND password = ?2")
        .expect("Failed to prepare query");

    let mut rows = stmt
        .query(params![req.email, req.password])
        .expect("Failed to execute query");

    if let Some(_) = rows.next().expect("Failed to fetch row") {
        let token = Uuid::new_v4().to_string();
        HttpResponse::Ok().json(LoginResponse {
            token,
            message: "Login successful".to_string(),
        })
    } else {
        HttpResponse::Unauthorized().json(ApiResponse {
            message: "Invalid email or password".to_string(),
        })
    }
}

async fn set_secret(req: web::Json<SetSecretRequest>) -> impl Responder {
    let conn = Connection::open("db.sqlite3").expect("Failed to open database");

    let result = conn.execute(
        "INSERT INTO secrets (username, secret) VALUES (?1, ?2)",
        params![req.username, req.secret],
    );

    match result {
        Ok(_) => HttpResponse::Ok().json(ApiResponse {
            message: "Secret has been set successfully".to_string(),
        }),
        Err(_) => HttpResponse::Unauthorized().json(ApiResponse {
            message: "Invalid authentication token".to_string(),
        }),
    }
}

async fn get_secret(query: web::Query<SetSecretRequest>) -> impl Responder {
    let conn = Connection::open("db.sqlite3").expect("Failed to open database");

    let mut stmt = conn
        .prepare("SELECT secret FROM secrets WHERE username = ?1")
        .expect("Failed to prepare query");

    let mut rows = stmt
        .query(params![query.username])
