      filename: './db.sqlite3',
      driver: sqlite3.Database,
    });

    await db.exec(`
      CREATE TABLE IF NOT EXISTS services (
        serviceId TEXT NOT NULL,
        token TEXT NOT NULL,
        lastNotification TEXT NOT NULL,
        PRIMARY KEY (serviceId, token)
      )
    `);

    this.db = db;
